1	// Cyrus mod planner: the DETERMINISTIC capability router over the planner's needs (pure, client-safe).
2	// The planner says what the prompt implies; this decides what Cyrus can build for THIS game, version, plan and host:
3	//   build    needed, and the game/version/plan/switches allow it (it goes into the build request)
4	//   skip     not needed (or the user switched it off)
5	//   blocked  needed but impossible here: the game/version cannot, a host switch is off, or the plan does not include it.
6	//            Each blocked lane has a plain warning (reason + substitute + "pick <version> or newer"). A plan with a
7	//            blocked lane needs an explicit "Continue anyway" before ANY tokens are held (lib/cyrus/planner/gate.ts).
8	// The approved lanes become the build's explicit `assets` request (toAssetsRequest), which the server re-checks.
9	import { canAsset } from "../engine-core/asset-gate";
10	import type { AssetKind } from "../engine-core/spec";
11	import { laneWarning, resolveLane, type CapabilityCatalogue, type CapabilityContext, type LaneCapability } from "../adapters/capabilities";
12	import { LANES, LANE_META, type Lane, type LaneNeed, type PlannerSource } from "./lanes";
13	
14	/** Lanes that create asset content go through the plan-tier gate (asset-gate.ts); designers, config and data are ungated. */
15	export const LANE_GATE: Partial<Record<Lane, AssetKind>> = { texture: "texture", itemStates: "texture", model3d: "model", creature: "model", sound: "sound", library: "sound" };
16	
17	export type LaneState = "build" | "skip" | "blocked";
18	export type PlannedLane = LaneNeed & {
19	  label: string;
20	  creates: string;
21	  state: LaneState;
22	  capability: LaneCapability;
23	  /** Why it is blocked (null otherwise). */
24	  warning: string | null;
25	  blockedBy: "version" | "game" | "flag" | "plan" | null;
26	  /** The plan that unlocks it when blockedBy = plan. */
27	  needsPlan?: string;
28	  /** true = the user flipped it (toggle) away from the planner's verdict. */
29	  toggled?: boolean;
30	};
31	export type ModPlan = {
32	  game: string;
33	  version: string;
34	  source: PlannerSource;
35	  lanes: PlannedLane[];
36	  /** Short list for the plan screen: what will be created. */
37	  creates: string[];
38	  /** Blocking-style warnings, one per blocked lane the prompt needs. */
39	  warnings: string[];
40	  /** true = the user must press "Continue anyway" before anything is held. */
41	  mustConfirm: boolean;
42	};
43	
44	export type DecideInput = {
45	  needs: LaneNeed[];
46	  source: PlannerSource;
47	  catalogue: CapabilityCatalogue | null | undefined;
48	  ctx: CapabilityContext;
49	  /** The account's plan tier (token economy); unknown = asset creation fails closed. */
50	  plan: unknown;
51	  change?: boolean;
52	  /** User toggles from the plan screen: lane -> wanted. */
53	  toggles?: Partial<Record<Lane, boolean>>;
54	};
55	
56	const PLAN_NAME: Record<string, string> = { saka: "Saka", all: "All models", katara: "Katara" };
57	
58	export function decidePlan(i: DecideInput): ModPlan {
59	  const lanes: PlannedLane[] = LANES.map((lane) => {
60	    const n = i.needs.find((x) => x.lane === lane) ?? { lane, need: false, why: "", confidence: 0.5 };
61	    const t = i.toggles?.[lane];
62	    const wanted = t === undefined ? n.need : t;
63	    const capability = resolveLane(i.catalogue, lane, i.ctx);
64	    const meta = LANE_META[lane];
65	    const base = { ...n, need: wanted, label: meta.label, creates: meta.creates, capability, ...(t !== undefined && t !== n.need ? { toggled: true } : {}) };
66	    if (!wanted) return { ...base, state: "skip" as const, warning: null, blockedBy: null };
67	    if (capability.availability === "unavailable") {
68	      const by = capability.cause === "ok" ? "game" : capability.cause;
69	      return { ...base, state: "blocked" as const, blockedBy: by, warning: laneWarning(capability, meta.label, i.ctx) };
70	    }
71	    const kind = LANE_GATE[lane];
72	    if (kind) {
73	      const g = canAsset(i.plan, kind, i.change ? "edit" : "create");
74	      if (!g.ok) {
75	        const sub = capability.substitute ? ` Cyrus will build ${capability.substitute} instead.` : "";
76	        return { ...base, state: "blocked" as const, blockedBy: "plan" as const, ...(g.needs ? { needsPlan: g.needs } : {}), warning: `${meta.label}: ${g.reason.replace(/\.$/, "")}.${sub}${g.needs ? ` Unlock the ${PLAN_NAME[g.needs] ?? g.needs} plan to get them.` : ""}` };
77	      }
78	    }
79	    return { ...base, state: "build" as const, warning: capability.availability === "limited" ? `${meta.label} are limited on ${i.ctx.gameName} ${i.ctx.version}: ${capability.reason}.` : null, blockedBy: null };
80	  });
81	  const warnings = lanes.filter((l) => l.state === "blocked" && l.warning).map((l) => l.warning!);
82	  return {
83	    game: i.ctx.game, version: i.ctx.version, source: i.source, lanes,
84	    creates: lanes.filter((l) => l.state === "build").map((l) => `${l.label}${l.why ? `: ${l.why}` : ""}`),
85	    warnings,
86	    mustConfirm: warnings.length > 0,
87	  };
88	}
89	
90	export const builtLanes = (p: Pick<ModPlan, "lanes">): Lane[] => p.lanes.filter((l) => l.state === "build").map((l) => l.lane);
91	
92	/**
93	 * The approved plan as the build's explicit `assets` request (lib/cyrus/assets/request.ts reads it). `plan: 1` marks a
94	 * PLANNED request: the server uses exactly these lanes instead of keyword matching (and still re-checks plan, version
95	 * and switches). Only lanes in state "build" are requested: a blocked lane never reaches the build.
96	 */
97	export type PlannedAssetsRequest = {
98	  plan: 1;
99	  lanes: Lane[];
100	  texture: boolean; sound: boolean; creature: boolean; itemmodel: boolean; datapack: boolean; worldgen: boolean; design: boolean; library: boolean;
101	  parts: { item: boolean; menus: boolean; quests: boolean; bosses: boolean; hud: boolean; motion: boolean };
102	  /** One short line per lane for the build service ("produce these"). */
103	  why: Partial<Record<Lane, string>>;
104	};
105	export function toAssetsRequest(p: Pick<ModPlan, "lanes">): PlannedAssetsRequest {
106	  const on = new Set(builtLanes(p));
107	  const parts = { item: on.has("designItem"), menus: on.has("designMenu"), quests: on.has("designQuest"), bosses: on.has("designBoss"), hud: on.has("designHud"), motion: on.has("motion") };
108	  return {
109	    plan: 1, lanes: LANES.filter((l) => on.has(l)),
110	    texture: on.has("texture") || on.has("itemStates") || on.has("model3d"), sound: on.has("sound") || on.has("library"), creature: on.has("creature"),
111	    itemmodel: on.has("itemStates"), datapack: on.has("datapack") || on.has("worldgen"), worldgen: on.has("worldgen"), library: on.has("library"),
112	    design: Object.values(parts).some(Boolean), parts,
113	    why: Object.fromEntries(p.lanes.filter((l) => l.state === "build" && l.why).map((l) => [l.lane, l.why.slice(0, 160)])),
114	  };
115	}
116	
117	/** Read a planned request back (server side). Null = not a planned request (keyword routing as before). */
118	export function readPlannedRequest(raw: unknown): PlannedAssetsRequest | null {
119	  if (!raw || typeof raw !== "object" || Array.isArray(raw) || (raw as { plan?: unknown }).plan !== 1) return null;
120	  const r = raw as Record<string, unknown>;
121	  const lanes = (Array.isArray(r.lanes) ? r.lanes : []).filter((l): l is Lane => (LANES as readonly string[]).includes(l as string));
122	  const on = new Set(lanes);
123	  const parts = { item: on.has("designItem"), menus: on.has("designMenu"), quests: on.has("designQuest"), bosses: on.has("designBoss"), hud: on.has("designHud"), motion: on.has("motion") };
124	  const why: Partial<Record<Lane, string>> = {};
125	  if (r.why && typeof r.why === "object") for (const [k, v] of Object.entries(r.why as Record<string, unknown>)) if (on.has(k as Lane) && typeof v === "string") why[k as Lane] = v.replace(/[<>]/g, "").slice(0, 160);
126	  // Rebuilt from the lane list only: the booleans a client sends are never trusted on their own.
127	  return { ...toAssetsRequest({ lanes: lanes.map((lane) => ({ lane, state: "build" } as PlannedLane)) }), parts, why };
128	}
129	// Cyrus mod planner: cost and time per model for a PLANNED build (pure, client-safe). The base is lib/cyrus/estimate.ts
130	// (measured builds); every lane the plan BUILDS adds its share (asset specs, designs and data packs are extra files the
131	// model writes and checks). Blocked lanes are never counted: the estimate is for what will really be built.
132	import { estimate, type Complexity } from "../estimate";
133	import { CYRUS_MODEL_IDS, type CyrusModelId } from "../models";
134	import type { Lane } from "./lanes";
135	
136	/** Extra share of a plain build's cost per built lane (time grows at 60% of that). Rough, from the R1-R5 flights. */
137	export const LANE_WEIGHT: Readonly<Partial<Record<Lane, number>>> = {
138	  texture: 0.25, itemStates: 0.1, sound: 0.2, model3d: 0.15, creature: 0.45, designItem: 0.15, designMenu: 0.15,
139	  designQuest: 0.2, designBoss: 0.25, designHud: 0.1, motion: 0.15, config: 0.05, datapack: 0.15, worldgen: 0.35, library: 0,
140	};
141	
142	export type ModelEstimate = { model: CyrusModelId; complexity: Complexity; usd: [number, number]; minutes: [number, number] };
143	
144	const r2 = (n: number) => Math.max(0.01, Math.round(n * 100) / 100);
145	
146	export function planEstimate(text: string, model: CyrusModelId, lanes: readonly Lane[], opts: { change?: boolean } = {}): ModelEstimate {
147	  const e = estimate(text, model, opts);
148	  const w = lanes.reduce((a, l) => a + (LANE_WEIGHT[l] ?? 0), 0);
149	  const k = 1 + w;
150	  const t = 1 + w * 0.6;
151	  const minutes: [number, number] = [Math.max(1, Math.round(e.minutes[0] * t)), Math.max(2, Math.round(e.minutes[1] * t))];
152	  if (minutes[1] <= minutes[0]) minutes[1] = minutes[0] + 1;
153	  return { model, complexity: e.complexity, usd: [r2(e.usd[0] * k), r2(e.usd[1] * k)], minutes };
154	}
155	
156	export const planEstimates = (text: string, lanes: readonly Lane[], opts: { change?: boolean } = {}): ModelEstimate[] =>
157	  CYRUS_MODEL_IDS.map((m) => planEstimate(text, m, lanes, opts));
158	
159	/**
160	 * The DEFAULT ("Auto") model: the cheapest model that is capable of the request. Katara only for trivial plain code
161	 * (the 2026-10-07 eval: the small model took 2x the turns on anything with structure), Saka for most mods (any asset or
162	 * designer lane), Yakko only for complex requests. Capped to what the plan unlocks (best allowed below the pick).
163	 */
164	export function autoModel(text: string, lanes: readonly Lane[], allowed: readonly CyrusModelId[] = CYRUS_MODEL_IDS): CyrusModelId {
165	  const e = estimate(text, "saka");
166	  const structured = lanes.some((l) => l !== "config");
167	  const pick: CyrusModelId = e.complexity === "complex" ? "yakko" : e.complexity === "simple" && !structured && e.score < 1.5 ? "katara" : "saka";
168	  const order: CyrusModelId[] = ["katara", "saka", "yakko"];
169	  if (allowed.includes(pick)) return pick;
170	  const below = order.slice(0, order.indexOf(pick) + 1).reverse().find((m) => allowed.includes(m));
171	  return below ?? allowed[0] ?? "katara";
172	}
173	// Cyrus mod planner: the EVAL HOOK. Scores lane selection against labelled prompts: the planner golden set
174	// (test/fixtures/cyrus-planner/golden.json) and the build eval set (services/modbuilder/eval, loadEvalSet), whose
175	// assetKinds / designer / route labels map onto planner lanes here. Pure; the needs function is injected, so the same
176	// scorer runs the deterministic rules (free, in CI) or the planner model (scripts, budgeted by the caller).
177	import type { EvalPrompt } from "../eval/set";
178	import { LANES, type Lane, type LaneNeed } from "./lanes";
179	
180	/** Asset-ish lanes: the ones over-requesting would cost money or promise assets. */
181	export const ASSET_LANES: readonly Lane[] = ["texture", "itemStates", "sound", "model3d", "creature", "designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion", "datapack", "worldgen"];
182	
183	export type LaneCase = { id: string; text: string; need: Lane[]; never?: Lane[]; plain?: boolean };
184	
185	/** An eval-set prompt as a lane case (labels: assetKinds, designer parts, route). */
186	export function caseFromEvalPrompt(p: EvalPrompt): LaneCase | null {
187	  if (p.must_refuse) return null;
188	  const k = p.assetKinds ?? [];
189	  const need = new Set<Lane>();
190	  if (k.includes("texture")) need.add("texture");
191	  if (k.includes("sound")) need.add("sound");
192	  if (k.includes("creature") || k.includes("model")) need.add("creature");
193	  for (const d of p.designer ?? []) {
194	    if (d === "item") need.add("designItem");
195	    if (d === "bosses") need.add("designBoss");
196	    if (d === "hud") need.add("designHud");
197	    if (d === "motion") need.add("motion");
198	  }
199	  if (p.route === "dataPack") need.add("datapack");
200	  const plain = p.route === "plugin" && !k.length && !(p.designer ?? []).length && ["commands", "gameplay", "stateful", "compat"].includes(p.category);
201	  return { id: p.key, text: p.prompt, need: [...need], plain };
202	}
203	
204	export type CaseScore = { id: string; ok: boolean; missing: Lane[]; extra: Lane[]; forbidden: Lane[] };
205	export function scoreCase(c: LaneCase, needs: LaneNeed[]): CaseScore {
206	  const got = new Set(needs.filter((n) => n.need).map((n) => n.lane));
207	  const missing = c.need.filter((l) => !got.has(l));
208	  const never = new Set<Lane>([...(c.never ?? []), ...(c.plain ? ASSET_LANES.filter((l) => !c.need.includes(l)) : [])]);
209	  const forbidden = [...never].filter((l) => got.has(l));
210	  const extra = ASSET_LANES.filter((l) => got.has(l) && !c.need.includes(l) && !never.has(l));
211	  return { id: c.id, ok: !missing.length && !forbidden.length, missing, extra, forbidden };
212	}
213	
214	export type SetScore = { cases: number; passed: number; recall: number; plainCases: number; plainOverRequested: number; results: CaseScore[] };
215	export function scoreSet(cases: LaneCase[], needsOf: (text: string) => LaneNeed[]): SetScore {
216	  const results = cases.map((c) => scoreCase(c, needsOf(c.text)));
217	  const wanted = cases.reduce((a, c) => a + c.need.length, 0);
218	  const hit = results.reduce((a, r, i) => a + (cases[i].need.length - r.missing.length), 0);
219	  const plain = cases.map((c, i) => [c, results[i]] as const).filter(([c]) => c.plain);
220	  return {
221	    cases: cases.length, passed: results.filter((r) => r.ok).length, recall: wanted ? Math.round((hit / wanted) * 100) / 100 : 1,
222	    plainCases: plain.length, plainOverRequested: plain.filter(([, r]) => r.forbidden.length > 0).length, results,
223	  };
224	}
225	
226	export { LANES };
227	// Cyrus mod planner: the PRE-BUILD gate (pure). A plan with a lane the prompt needs but this game/version/plan cannot
228	// produce must be confirmed ("Continue anyway") BEFORE any tokens are held: lib/modbuilder/create.ts calls this before
229	// gateBuild (the hold), so a refused request never creates a reservation. API callers that cannot show a plan screen
230	// (API v1, the plain builds route) pass `requireAck: false` and get the same warnings back as asset notices instead.
231	import type { ModPlan } from "./decide";
232	
233	export type PreBuildCheck = { ok: true } | { ok: false; status: 409; json: { error: string; code: "plan_confirm"; warnings: string[] } };
234	
235	export function preBuildCheck(plan: Pick<ModPlan, "mustConfirm" | "warnings">, opts: { requireAck: boolean; ack: unknown }): PreBuildCheck {
236	  if (!opts.requireAck || !plan.mustConfirm || opts.ack === true) return { ok: true };
237	  return { ok: false, status: 409, json: { code: "plan_confirm", warnings: plan.warnings, error: `Before you spend anything: ${plan.warnings[0]}${plan.warnings.length > 1 ? ` (and ${plan.warnings.length - 1} more)` : ""} Press "Continue anyway" to build without it.` } };
238	}
239	// Cyrus MOD PLANNER (live-test fix, item F): the LANES a mod request can need, and the planner's output contract.
240	// Pure + client-safe. The planner (a cheap Haiku call on the build service, services/modbuilder/planner.js, with the
241	// deterministic rules in ./rules.ts as the fallback) says which lanes the PROMPT implies; the deterministic capability
242	// router (./decide.ts) stays the authority on what can be built (game/version, plan, flags) and says why not.
243	import { z } from "zod";
244	
245	export const LANES = [
246	  "texture", "itemStates", "sound", "model3d", "creature",
247	  "designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion",
248	  "config", "datapack", "worldgen", "library",
249	] as const;
250	export type Lane = (typeof LANES)[number];
251	export const isLane = (v: unknown): v is Lane => typeof v === "string" && (LANES as readonly string[]).includes(v);
252	
253	/** Customer wording per lane (what it creates). */
254	export const LANE_META: Record<Lane, { label: string; creates: string }> = {
255	  texture: { label: "Custom textures", creates: "item and block looks drawn for this mod" },
256	  itemStates: { label: "Item looks per state", creates: "a different look while pulling, aiming, charging or in a mode" },
257	  sound: { label: "Custom sounds", creates: "new sound effects or music with subtitles" },
258	  model3d: { label: "3D models", creates: "shaped 3D looks beyond a flat item" },
259	  creature: { label: "Animated creature models", creates: "an animated custom mob model and skin" },
260	  designItem: { label: "Item with abilities", creates: "a typed item design: triggers, cooldowns, effects" },
261	  designMenu: { label: "Menus", creates: "chest-menu GUIs, shops and dialogues" },
262	  designQuest: { label: "Quests", creates: "objectives, chains, daily tasks and rewards" },
263	  designBoss: { label: "Boss fight", creates: "phases, telegraphed attacks, waves, a boss bar" },
264	  designHud: { label: "HUD", creates: "glyph bars and icons in the action bar, boss bar or sidebar" },
265	  motion: { label: "Animated props", creates: "doors, hatches, turrets and moving display-entity props" },
266	  config: { label: "Settings", creates: "editable tunables (damage, cooldowns, messages) in config.yml" },
267	  datapack: { label: "Data pack", creates: "recipes, loot tables, advancements, tags" },
268	  worldgen: { label: "World generation", creates: "biomes, structures, a dimension" },
269	  library: { label: "Library assets", creates: "ready-made sounds or textures from the Nxeon library" },
270	};
271	
272	const LaneVerdict = z.object({
273	  need: z.boolean(),
274	  why: z.string().max(240).default(""),
275	  confidence: z.number().min(0).max(1).default(0.5),
276	});
277	/** What the planner model must answer: one verdict per lane it mentions (missing lanes = not needed). */
278	export const PlannerOutput = z.object({ lanes: z.record(z.string(), LaneVerdict) });
279	export type LaneNeed = { lane: Lane; need: boolean; why: string; confidence: number };
280	export type PlannerSource = "planner" | "rules";
281	export type Needs = { source: PlannerSource; lanes: LaneNeed[]; costUsd?: number; ms?: number; error?: string };
282	
283	/** Parse + validate the planner model's text (it may wrap the JSON in a code fence). Null = invalid: use the rules. */
284	export function parsePlannerText(raw: unknown): LaneNeed[] | null {
285	  if (typeof raw !== "string" || !raw.trim()) return null;
286	  const s = raw.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
287	  const a = s.indexOf("{"), b = s.lastIndexOf("}");
288	  if (a < 0 || b <= a) return null;
289	  let json: unknown;
290	  try { json = JSON.parse(s.slice(a, b + 1)); } catch { return null; }
291	  const p = PlannerOutput.safeParse(json);
292	  if (!p.success) return null;
293	  const out: LaneNeed[] = [];
294	  for (const lane of LANES) {
295	    const v = p.data.lanes[lane];
296	    out.push(v ? { lane, need: v.need, why: v.why.slice(0, 200), confidence: Math.round(v.confidence * 100) / 100 } : { lane, need: false, why: "", confidence: 0.5 });
297	  }
298	  return out;
299	}
300	// Cyrus mod planner: the DETERMINISTIC needs analysis (zero cost, no network). It is the fallback when the planner
301	// model is unavailable, slow or answers invalid JSON, and the floor under it: a lane a literal phrase asks for
302	// ("custom texture", "boss fight") is never dropped. It reuses every existing route matcher (adapter route rules,
303	// designer / data pack / item state words) and adds what the live test showed was missing: what a mod implies
304	// without saying the words (a golem that "grunts" needs sounds; a creature that "throws rocks" needs a rock item
305	// texture; "make it look cool" needs textures). Plain-code requests (commands, rules, chat) get no asset lanes.
306	import { detectAssetKinds } from "../assets/plan";
307	import { creatureLike } from "../assets/auto";
308	import { matchBossWords, matchDesignerWords, matchGameplayWords, matchHudWords, matchMotionWords, ITEM_WORDS } from "../designer/route";
309	import { matchDataPackRules, WORLDGEN_RULE } from "../datapack/route";
310	import { matchStateWords } from "../itemmodel/route";
311	import { LANES, type Lane, type LaneNeed } from "./lanes";
312	
313	/** Sounds the request implies (a voice, an effect, music), even without the word "sound". */
314	export const SOUND_WORDS = /\b(sounds?|sfx|music|songs?|soundtracks?|jingles?|chimes?|bells?|grunt(?:s|ing)?|groan(?:s|ing)?|roar(?:s|ing)?|growl(?:s|ing)?|scream(?:s|ing)?|shriek(?:s|ing)?|hiss(?:es|ing)?|howl(?:s|ing)?|bark(?:s|ing)?|moan(?:s|ing)?|voice(?:s|d| lines?)?|noises?|ambien(?:ce|t)|audio|beeps?|whoosh|thunder ?claps?|war ?cry|battle ?cry|sirens?|alarms?|hum(?:s|ming)?|rings? (?:a|the|out)|synth\w*|tracks?)\b/i;
315	const NO_SOUND = /\b(no|without|silent|mute[sd]?) (?:custom )?(?:sounds?|audio|music)\b/i;
316	/** Looks the request implies: a named custom item, glowing / legendary gear, a skin, "look cool". */
317	const LOOK_WORDS = /\b(textures?|retextur\w*|skins?|icons?|looks? (?:cool|awesome|epic|unique|different|like)|glow(?:s|ing)?|shiny|sparkl\w*|custom (?:items?|weapons?|armou?r|tools?|blocks?|looks?)|new (?:items?|weapons?|armou?r|tools?)|legendary|art ?style|pixel art|colou?rful|drawn|pictures?|sprites?)\b/i;
318	/** Material / element adjectives: a look only when they describe an item ("a ruby sword", "a frost staff"). */
319	const ITEM_ADJ = /\b(custom|new|special|magic(?:al)?|legendary|named|mythic|ancient|cursed|purple|golden|crystal|ruby|emerald|sapphire|amethyst|obsidian|flaming|fiery|frost|ice|lightning|thunder|shadow|void|blood)\b/i;
320	/** Things a creature or item throws / drops that deserve their own item look. */
321	const THROWN = /\b(th?r?ows?|throwing|hurls?|hurling|launch(?:es)?|shoots?|tosses?|drops?|spits?)\b[^.]{0,30}\b(rocks?|boulders?|stones?|spears?|bombs?|orbs?|fireballs?|balls?|crystals?|shards?|gems?|daggers?|knives|bones?|items?)\b/i;
322	/** A NEW creature (not "zombie kills give coins"). */
323	const NEW_CREATURE = /\b(creatures?|golems?|\d+ blocks? tall|giant (?:mob|creature|monster|golem|spider|beast)|custom (?:mobs?|creatures?|monsters?|pets?|npcs?)|new (?:mobs?|creatures?|monsters?|pets?)|summon(?:s|able)? (?:a|an|my)? ?(?:pet|creature|minion|golem|beast)|tameable|companion pets?)\b/i;
