325	const MOTION_EXTRA = /\b(spinning|spins|rotat(?:es|ing)|orbit(?:s|ing)?|sways?|swaying|bobs?|bobbing|waving|floating (?:display|crystal|prop|item)s?)\b/i;
326	/** On-screen things a server cannot draw freely (still a HUD lane: the router says what is possible). */
327	const SCREEN_WORDS = /\b(mini-?maps?|on[- ]screen (?:display|widget|overlay)s?|hud)\b/i;
328	const MODEL_WORDS = /\b(3d|three[- ]d|3-d)\b|\b(statues?|sculptures?|furniture|custom (?:entity|mob|creature|block) models?|display entit(?:y|ies))\b/i;
329	const TUNABLE_WORDS = /\b(config(?:urable)?|settings?|adjust(?:able)?|customi[sz]able|cooldowns?|damage|amounts?|every \d+|rates?|chances?|percent|%|\d+ (?:seconds?|minutes?|blocks?|hearts?|coins?)|radius|range|duration|limits?|prices?|rewards?)\b/i;
330	
331	const need = (lane: Lane, yes: boolean, why: string, confidence = 0.7): LaneNeed => ({ lane, need: yes, why: yes ? why : "", confidence: yes ? confidence : 0.6 });
