333	/** The deterministic needs for a request (no AI). Order = LANES. */
334	export function ruleNeeds(text: string, game = "minecraft"): LaneNeed[] {
335	  const t = (text ?? "").trim();
336	  const literal = new Set(detectAssetKinds(t, game));
337	  const creature = NEW_CREATURE.test(t) || (literal.has("creature")) || (creatureLike(t) && /\b(tall|giant|huge|spawn|summon|throws?|attacks?|follows?|pet)\b/i.test(t));
338	  const item = matchDesignerWords(t);
339	  const gp = matchGameplayWords(t);
340	  const boss = matchBossWords(t);
341	  const hud = matchHudWords(t);
342	  const motion = matchMotionWords(t);
343	  const dp = matchDataPackRules(t, game, { worldgen: true });
344	  const sound = !NO_SOUND.test(t) && (literal.has("sound") || SOUND_WORDS.test(t));
345	  const thrown = THROWN.exec(t);
346	  const namedItem = ITEM_WORDS.test(t) && (item.length > 0 || LOOK_WORDS.test(t) || ITEM_ADJ.test(t));
347	  const texture = literal.has("texture") || LOOK_WORDS.test(t) || namedItem || (!!thrown && creature);
348	  const states = texture && matchStateWords(t).length > 0;
349	  const by: Record<Lane, LaneNeed> = {
350	    texture: need("texture", texture, literal.has("texture") ? "the request asks for custom textures" : thrown && creature ? `the ${thrown[2].toLowerCase()} it ${thrown[1].toLowerCase()} can have its own look` : namedItem ? "a custom item gets its own look" : "the request asks for a custom look", literal.has("texture") ? 0.95 : 0.65),
351	    itemStates: need("itemStates", states, "the item can look different per state (pulling, aiming, charging)", 0.6),
352	    sound: need("sound", sound, literal.has("sound") ? "the request asks for custom sounds" : `the request describes sounds (${(SOUND_WORDS.exec(t)?.[0] ?? "sound").toLowerCase()})`, literal.has("sound") ? 0.95 : 0.7),
353	    model3d: need("model3d", MODEL_WORDS.test(t), "the request describes a 3D shape", 0.6),
354	    creature: need("creature", creature, "the request describes a new creature with its own look", 0.75),
355	    designItem: need("designItem", item.length > 0, "an item with abilities (trigger, cooldown, effect)", 0.75),
356	    designMenu: need("designMenu", gp.menus, "the request describes a menu, shop or dialogue", 0.8),
357	    designQuest: need("designQuest", gp.quests, "the request describes quests or missions", 0.8),
358	    designBoss: need("designBoss", boss.length > 0, "the request describes a boss fight or waves", 0.8),
359	    designHud: need("designHud", hud.hud || hud.excluded || SCREEN_WORDS.test(t), hud.hud ? "the request describes a HUD bar or icons" : "the request asks for something drawn on screen", 0.75),
360	    motion: need("motion", motion.length > 0 || MOTION_EXTRA.test(t), "the request describes moving props", 0.7),
361	    config: need("config", TUNABLE_WORDS.test(t), "it has numbers an owner will want to tune", 0.6),
362	    datapack: need("datapack", dp.some((r) => r !== WORLDGEN_RULE), "recipes, loot, advancements or tags", 0.8),
363	    worldgen: need("worldgen", dp.includes(WORLDGEN_RULE), "biomes, structures or a dimension", 0.85),
364	    library: need("library", sound && /\b(music|ambien\w*|footsteps?|explosions?|bells?|chimes?|jingles?|rain|thunder)\b/i.test(t), "stock sounds fit (music, ambience, effects)", 0.5),
365	  };
366	  return LANES.map((l) => by[l]);
367	}
