369	/** Lanes a literal phrase asks for: kept even when the planner model says no (never drop an explicit ask). */
370	export function literalLanes(text: string, game = "minecraft"): Lane[] {
371	  const k = detectAssetKinds(text, game);
372	  const out: Lane[] = [];
373	  if (k.includes("texture")) out.push("texture");
374	  if (k.includes("sound")) out.push("sound");
375	  if (k.includes("creature")) out.push("creature");
376	  if (matchBossWords(text).length) out.push("designBoss");
377	  const dp = matchDataPackRules(text, game, { worldgen: true });
378	  if (dp.includes(WORLDGEN_RULE)) out.push("worldgen");
379	  if (dp.some((r) => r !== WORLDGEN_RULE)) out.push("datapack");
380	  return out;
381	}
