383	/** Merge the planner's verdicts with the literal floor (a literal ask always stays). */
384	export function mergeNeeds(planner: LaneNeed[] | null, text: string, game = "minecraft"): { lanes: LaneNeed[]; source: "planner" | "rules" } {
385	  if (!planner) return { lanes: ruleNeeds(text, game), source: "rules" };
386	  const floor = new Set(literalLanes(text, game));
387	  const rules = ruleNeeds(text, game);
388	  return {
389	    source: "planner",
390	    lanes: planner.map((n) => (!n.need && floor.has(n.lane) ? { ...rules.find((r) => r.lane === n.lane)!, need: true } : n)),
391	  };
392	}
393	// Cyrus mod planner: the SERVER flow (dependencies injectable, so the whole path is tested with fakes and no model call).
394	//   1. needs:  the planner model on the build service (POST /plan, ~$0.001, 9 s budget) validated with zod; on any
395	//              failure, timeout or invalid answer: the deterministic rules (lib/cyrus/planner/rules.ts). A literal ask
396	//              ("custom texture") is never dropped.
397	//   2. decide: the capability router over the game's catalogue + plan tier + host switches (./decide.ts).
398	//   3. price:  cost / time / tokens per model for the lanes that will really be built (./estimate.ts + the economy).
399	import { createHash } from "node:crypto";
400	import { getAdapter } from "../adapters";
401	import type { CapabilityCatalogue, CapabilityContext } from "../adapters/capabilities";
402	import { modelsFor, holdRange, tokensForCost } from "../tokens/economy";
403	import type { TokenConfig, TokenTier } from "../tokens/config";
404	import type { CyrusModelId } from "../models";
405	import { builtLanes, decidePlan, toAssetsRequest, type ModPlan, type PlannedAssetsRequest } from "./decide";
406	import { autoModel, planEstimates } from "./estimate";
407	import { parsePlannerText, type Lane, type LaneNeed, type Needs } from "./lanes";
408	import { mergeNeeds } from "./rules";
409	
410	export type PlannerAsk = (body: { text: string; game: string; mcVersion: string }) => Promise<{ text: string | null; costUsd: number; ms: number }>;
411	export type PlannerDeps = {
412	  /** The build service planner (svcPlan). Absent = rules only. */
413	  ask?: PlannerAsk;
414	  /** Does the service have POST /plan (health features.planner)? */
415	  supports?: () => Promise<boolean>;
416	  timeoutMs?: number;
417	};
418	
419	const CACHE = new Map<string, { at: number; needs: Needs }>();
420	const CACHE_MS = 10 * 60_000;
421	const key = (t: string, g: string, v: string) => createHash("sha256").update(`${g}\n${v}\n${t.trim().toLowerCase()}`).digest("hex");
422	
423	/** What the prompt needs: the planner model when it answers in time with valid JSON, else the rules. */
424	export async function analyzeNeeds(input: { text: string; game: string; mcVersion: string }, deps: PlannerDeps = {}): Promise<Needs> {
425	  const k = key(input.text, input.game, input.mcVersion);
426	  const hit = CACHE.get(k);
427	  if (hit && Date.now() - hit.at < CACHE_MS) return hit.needs;
428	  let needs: Needs;
429	  const rules = (error?: string): Needs => ({ ...mergeNeeds(null, input.text, input.game), ...(error ? { error } : {}) });
430	  if (!deps.ask || !(await (deps.supports ?? (async () => true))().catch(() => false))) needs = rules("planner not available");
431	  else {
432	    const t0 = Date.now();
433	    try {
434	      const timeout = new Promise<null>((r) => setTimeout(() => r(null), deps.timeoutMs ?? 9000));
435	      const ans = await Promise.race([deps.ask(input), timeout]);
436	      const parsed = ans ? parsePlannerText(ans.text) : null;
437	      if (!ans) needs = rules("planner timed out");
438	      else if (!parsed) needs = { ...rules("planner answer was not valid"), costUsd: ans.costUsd };
439	      else needs = { ...mergeNeeds(parsed, input.text, input.game), costUsd: ans.costUsd, ms: ans.ms || Date.now() - t0 };
440	    } catch (e) {
441	      needs = rules(`planner failed: ${(e as Error).message.slice(0, 80)}`);
442	    }
443	  }
444	  if (CACHE.size > 300) CACHE.clear();
445	  CACHE.set(k, { at: Date.now(), needs });
446	  return needs;
447	}
