449	/** The host switches the capability catalogue reads (server side; fail closed: unset = off). */
450	export function hostFlags(env: Record<string, string | undefined> = process.env): Record<string, boolean> {
451	  const on = (k: string) => env[k] === "1";
452	  return {
453	    CYRUS_DESIGNER: on("CYRUS_DESIGNER"), CYRUS_ITEM_STATES: on("CYRUS_ITEM_STATES"), CYRUS_CREATURES: on("CYRUS_CREATURES"),
454	    CYRUS_DATAPACK_STUDIO: on("CYRUS_DATAPACK_STUDIO"), CYRUS_WORLDGEN: on("CYRUS_DATAPACK_STUDIO") && on("CYRUS_WORLDGEN"),
455	    CYRUS_SOUND_LIBRARY_CLEARED: on("CYRUS_SOUND_LIBRARY_CLEARED"), CYRUS_CONFIG_STUDIO: on("CYRUS_CONFIG_STUDIO"),
456	  };
457	}
458	
459	export function capabilityContext(game: string, version: string, flags: Record<string, boolean>): { ctx: CapabilityContext; catalogue: CapabilityCatalogue | undefined } {
460	  const a = getAdapter(game);
461	  return {
462	    ctx: { game, gameName: a?.name ?? game, version, hasCapability: (c) => !!a?.versions.hasCapability(version, c), flags },
463	    catalogue: a?.capabilities,
464	  };
465	}
