467	export type ModelOption = { model: CyrusModelId; usd: [number, number]; minutes: [number, number]; tokens: [number, number] | null; hold: number | null; allowed: boolean };
468	export type PlanResponse = {
469	  plan: ModPlan;
470	  /** The explicit `assets` request for the build (only lanes in state "build"). */
471	  assets: PlannedAssetsRequest;
472	  models: ModelOption[];
473	  /** The Auto pick (cheapest capable model the plan unlocks). */
474	  auto: CyrusModelId;
475	  planner: { source: Needs["source"]; costUsd: number; ms: number | null; error: string | null };
476	};
477	
478	/** The full pre-build plan for the plan screen (and the server-side plan of a build that came without one). */
479	export async function buildModPlan(input: { text: string; game: string; mcVersion: string; tier: TokenTier | null; change?: boolean; toggles?: Partial<Record<Lane, boolean>>; cfg?: TokenConfig | null; needs?: LaneNeed[] | null; source?: Needs["source"] },
480	  deps: PlannerDeps & { flags?: Record<string, boolean> } = {}): Promise<PlanResponse> {
481	  const needs: Needs = input.needs ? { source: input.source ?? "rules", lanes: input.needs } : await analyzeNeeds({ text: input.text, game: input.game, mcVersion: input.mcVersion }, deps);
482	  const { ctx, catalogue } = capabilityContext(input.game, input.mcVersion, deps.flags ?? hostFlags());
483	  const plan = decidePlan({ needs: needs.lanes, source: needs.source, catalogue, ctx, plan: input.tier, change: input.change, toggles: input.toggles });
484	  const lanes = builtLanes(plan);
485	  const allowed = input.tier ? modelsFor(input.tier) : (["katara", "saka", "yakko"] as CyrusModelId[]);
486	  const cfg = input.cfg ?? null;
487	  const models: ModelOption[] = planEstimates(input.text, lanes, { change: input.change }).map((e) => {
488	    const tokens: [number, number] | null = cfg ? [tokensForCost(e.usd[0], e.model, cfg), tokensForCost(e.usd[1], e.model, cfg)] : null;
489	    return { model: e.model, usd: e.usd, minutes: e.minutes, tokens, hold: cfg ? holdRange(e.model, e.complexity, cfg, e.usd)[1] : null, allowed: allowed.includes(e.model) };
490	  });
491	  return {
492	    plan, assets: toAssetsRequest(plan), models, auto: autoModel(input.text, lanes, allowed),
493	    planner: { source: needs.source, costUsd: needs.costUsd ?? 0, ms: needs.ms ?? null, error: needs.error ?? null },
494	  };
495	}
