"use client";

// Live-test fix (F): the PLAN screen before a real build. Shows what Cyrus will create (lanes from the mod planner,
// decided by the capability router), what cannot be built on this game/version/plan and why, the cost and time per
// model (blocked lanes not counted), and lets the user toggle lanes and pick a model. Nothing is held until "Build"
// (or "Continue anyway" when a needed lane is impossible here).
import { useEffect, useRef } from "react";
import { forge, openPlan } from "@/lib/cyrus/forge";
import { MODEL_BY_ID } from "@/lib/cyrus/data";
import { useStore } from "@/lib/cyrus/store";
import type { Lane } from "@/lib/cyrus/planner/lanes";
import type { CyrusModelId } from "@/lib/cyrus/models";

const usd = (r: [number, number]) => `$${r[0].toFixed(2)}–${r[1].toFixed(2)}`;
const mins = (r: [number, number]) => `${r[0]}–${r[1]} min`;
const tok = (r: [number, number] | null) => (r ? `${r[0].toLocaleString("en-US")}–${r[1].toLocaleString("en-US")} tokens` : null);

export function PlanSheet() {
  const draft = useStore((s) => s.planDraft);
  const modelAuto = useStore((s) => s.modelAuto);
  const model = useStore((s) => s.model);
  const setModel = useStore((s) => s.setModel);
  const setModelAuto = useStore((s) => s.setModelAuto);
  const mcVersion = useStore((s) => s.mcVersion);
  const close = () => useStore.getState().setPlanDraft(null);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!draft) return;
    ref.current?.focus();
    const esc = (e: KeyboardEvent) => e.key === "Escape" && close();
    window.addEventListener("keydown", esc);
    return () => window.removeEventListener("keydown", esc);
  }, [draft?.text]); // eslint-disable-line react-hooks/exhaustive-deps
  if (!draft) return null;
  const res = draft.res;
  const toggle = (lane: Lane, on: boolean) => void openPlan(draft.text, draft.images, { ...draft.toggles, [lane]: on });
  const build = () => {
    if (!res) return;
    void forge(draft.text, draft.images, { assets: res.assets, planAck: res.plan.mustConfirm, plannerSource: res.planner.source === "planner" ? "planner" : "rules" });
  };
  const building = res?.plan.lanes.filter((l) => l.state === "build") ?? [];
  const blocked = res?.plan.lanes.filter((l) => l.state === "blocked") ?? [];
  const addable = res?.plan.lanes.filter((l) => l.state === "skip" && l.capability.availability !== "unavailable") ?? [];
  const chosen: CyrusModelId | null = res ? (modelAuto ? res.auto : model) : null;

  return (
    <div ref={ref} tabIndex={-1} role="dialog" aria-modal="false" aria-label="Plan for this mod" className="cy5-solid animate-pop mb-2 max-h-[min(70vh,620px)] overflow-y-auto rounded-2xl p-3 text-[13px] text-cy-ink outline-none">
      <div className="flex items-center gap-2 pb-2">
        <b className="font-cy-display text-[14px]" data-testid="cyrus-plan-target">{draft.target ? <>Change {draft.target.name} → v{draft.target.version}</> : "Plan for a new mod"}</b>
        <span className="rounded-full bg-[rgb(var(--glow)/0.1)] px-2 py-0.5 text-[10.5px] text-cy-muted">Minecraft · Paper {res?.plan.version ?? mcVersion}</span>
        {res && <span className="text-[10.5px] text-cy-faint" title={res.planner.error ?? undefined}>{res.planner.source === "planner" ? "planned by Cyrus" : "quick plan (rules)"}</span>}
        <button type="button" onClick={close} className="ml-auto rounded-lg px-2 py-1 text-[12px] text-cy-muted hover:text-cy-ink" aria-label="Close the plan">Cancel</button>
      </div>
      {draft.loading && !res && <p className="py-3 text-cy-muted" aria-live="polite">Reading your request and checking what this version can do…</p>}
      {draft.error && <p className="py-2 text-rose-400" role="alert">{draft.error}</p>}
      {res && (
        <>
          {blocked.length > 0 && (
            <div role="alert" className="mb-2 rounded-xl border border-amber-400/40 bg-amber-400/10 p-2.5">
              <b className="block pb-1 text-[12.5px]">Before you spend anything</b>
              <ul className="list-disc space-y-1 pl-4 text-[12.5px] leading-snug">
                {blocked.map((l) => <li key={l.lane}>{l.warning}</li>)}
              </ul>
            </div>
          )}
          <div className="pb-2">
            <div className="pb-1 text-[10.5px] font-semibold uppercase tracking-[0.14em] text-cy-muted">Cyrus will create</div>
            {building.length === 0 && <p className="text-cy-muted">Plugin code only (commands, events, settings). No custom assets needed.</p>}
            <ul className="space-y-1">
              {building.map((l) => (
                <li key={l.lane} className="flex items-start gap-2">
                  <input type="checkbox" checked onChange={() => toggle(l.lane, false)} aria-label={`Remove ${l.label}`} className="mt-0.5 accent-violet-500" disabled={draft.loading} />
                  <span><b>{l.label}</b>{l.why ? <span className="text-cy-muted"> · {l.why}</span> : null}{l.warning ? <span className="block text-[11.5px] text-amber-300">{l.warning}</span> : null}</span>
                </li>
              ))}
            </ul>
            {addable.length > 0 && (
              <details className="pt-1.5">
                <summary className="cursor-pointer text-[12px] text-cy-muted">Add more ({addable.length})</summary>
                <ul className="space-y-1 pt-1">
                  {addable.map((l) => (
                    <li key={l.lane} className="flex items-start gap-2">
                      <input type="checkbox" checked={false} onChange={() => toggle(l.lane, true)} aria-label={`Add ${l.label}`} className="mt-0.5 accent-violet-500" disabled={draft.loading} />
                      <span><b>{l.label}</b> <span className="text-cy-muted">· {l.creates}</span></span>
                    </li>
                  ))}
                </ul>
              </details>
            )}
          </div>
          <div className="pb-2" role="radiogroup" aria-label="Model">
            <div className="pb-1 text-[10.5px] font-semibold uppercase tracking-[0.14em] text-cy-muted">Model · estimate for what will be built</div>
            <label className="flex cursor-pointer items-center gap-2 rounded-lg px-1.5 py-1 hover:bg-[rgb(var(--glow)/0.06)]">
              <input type="radio" name="cy-plan-model" checked={modelAuto} onChange={() => setModelAuto(true)} className="accent-violet-500" />
              <span><b>Auto</b> <span className="text-cy-muted">· picks {MODEL_BY_ID[res.auto].name}, the cheapest model that can build this</span></span>
            </label>
            {res.models.map((m) => (
              <label key={m.model} className={`flex items-center gap-2 rounded-lg px-1.5 py-1 ${m.allowed ? "cursor-pointer hover:bg-[rgb(var(--glow)/0.06)]" : "opacity-50"}`}>
                <input type="radio" name="cy-plan-model" disabled={!m.allowed} checked={!modelAuto && model === m.model} onChange={() => setModel(m.model)} className="accent-violet-500" />
                <span className="min-w-[64px]"><b>{MODEL_BY_ID[m.model].name}</b></span>
                <span className="tabular-nums text-cy-muted">{mins(m.minutes)} · {tok(m.tokens) ?? usd(m.usd)}{m.hold ? ` · holds up to ${m.hold.toLocaleString("en-US")}` : ""}{!m.allowed ? " · not on your plan" : ""}</span>
              </label>
            ))}
          </div>
          <div className="flex items-center gap-2 pt-1">
            <span className="text-[11px] text-cy-faint">{chosen ? `${MODEL_BY_ID[chosen].name} builds it. Only what it uses is charged.` : ""}</span>
            <button type="button" onClick={close} className="ml-auto rounded-xl px-3 py-2 text-[12.5px] text-cy-muted hover:text-cy-ink">Cancel</button>
            <button type="button" onClick={build} disabled={draft.loading || res.buildable === false} className="rounded-xl px-3.5 py-2 text-[12.5px] font-semibold text-white disabled:opacity-40" style={{ background: "linear-gradient(135deg, #8b5cf6, #6366f1 45%, #06b6d4)" }}>
              {res.buildable === false ? "Not buildable yet" : res.plan.mustConfirm ? "Continue anyway" : "Build"}
            </button>
          </div>
        </>
      )}
    </div>
  );
}

