/** Live-test fix (F): open (or refresh, with toggles) the plan screen for a request. Nothing is held or charged. */
export async function openPlan(prompt: string, images: ForgeImage[] = [], toggles: import("./store").PlanDraft["toggles"] = {}) {
  const st = useStore.getState();
  const sel = st.selection;
  const picked = sel.level === "mod" ? findMod(sel.modId) : undefined;
  const change = !!(picked && !picked.idea && picked.real);
  const target = change && picked ? { modId: picked.id, name: picked.name, version: versionsOf(picked, st.userVersions).length + 1 } : null;
  st.setPlanDraft({ text: prompt, images, res: st.planDraft?.text === prompt ? st.planDraft.res : null, toggles, target, loading: true });
  try {
    const r = await fetch("/api/cyrus/plan", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ prompt, mcVersion: st.mcVersion, change, toggles }) });
    const j = (await r.json().catch(() => ({}))) as Record<string, unknown>;
    if (useStore.getState().planDraft?.text !== prompt) return; // closed or replaced meanwhile
    if (!r.ok) { useStore.getState().setPlanDraft({ text: prompt, images, res: null, toggles, target, loading: false, error: String(j.error ?? "Cyrus couldn't plan this right now.") }); return; }
    useStore.getState().setPlanDraft({ text: prompt, images, res: j as unknown as NonNullable<import("./store").PlanDraft["res"]>, toggles, target, loading: false });
  } catch {
    if (useStore.getState().planDraft?.text === prompt) useStore.getState().setPlanDraft({ text: prompt, images, res: null, toggles, target, loading: false, error: "Cyrus couldn't reach the planner. Try again." });
  }
}

let pendingTarget: import("./store").PlanDraft["target"] = null;

export async function forge(prompt: string, images: ForgeImage[] = [], approved?: ApprovedPlan) {
  // Live-test fix: the build lands on the mod the plan screen showed as its target, even if the selection moved meanwhile.
  const planned = useStore.getState().planDraft;
  if (approved && planned?.text === prompt.trim()) {
    const t = planned.target;
    const sel = useStore.getState().selection;
    if (t && !(sel.level === "mod" && sel.modId === t.modId)) {
      const m = findMod(t.modId);
      if (m) useStore.getState().select({ level: "mod", gameId: m.gameId, category: m.category, modId: m.id }, { openPanel: true });
    }
    pendingTarget = t;
  }
  const state = useStore.getState();
  if (isJobLive(state.job)) return;
  const text = prompt.trim();
  if (!text) return;
  // Free, instant refusals before any job exists: not a mod request, or a game Cyrus cannot build for yet.
  const unclear = promptProblem(text);
  if (unclear) {
    state.toast({ tone: "info", title: "Tell Cyrus what to build", body: unclear });
    return;
  }
  const model = MODEL_BY_ID[state.model];

  const sel = state.selection;
  const picked = sel.level === "mod" ? findMod(sel.modId) : undefined;
  // An idea pill is a prompt, not a mod: a forge from it is a brand-new mod in its category.
  const refineMod = picked?.idea ? undefined : picked;
  // Cyrus v6 community: a library node is someone else's mod. It changes only through a remix.
  if (refineMod?.library) {
    state.toast({ tone: "info", title: "Remix it first", body: `${refineMod.name} is ${refineMod.library.creator}'s mod. Press "Remix in my Cyrus" in its panel to get your own copy, then ask for changes.` });
    return;
  }
  if (refineMod?.real && !refineMod.real.headBuildId) {
    state.toast({
      tone: "error",
      title: "Nothing to change yet",
      body: refineMod.real.running ? "Cyrus is still building this mod. Ask for the next change when it's ready." : "This mod has no version that built. Describe it again to forge a new one.",
    });
    return;
  }
  const targetGame = refineMod ? getGame(refineMod.gameId) : sel.gameId ? getGame(sel.gameId) : undefined;
  if (targetGame && !gameIsLive(targetGame) && !refineMod?.real) {
    state.toast({ tone: "info", title: `${targetGame.name} is coming soon`, body: "Cyrus builds Minecraft plugins today. Pick Minecraft, or ask for a Minecraft mod." });
    return;
  }
  // Live-test fix (F): a real build shows its PLAN first (lanes, what is impossible here, cost per model). The plan
  // screen calls forge() again with the approved lanes; nothing is held before that.
  if (!approved) { void openPlan(text, images); return; }
  pendingAsk = { text, images };
  const autoPick = state.planDraft?.res?.auto;
  useStore.setState({ planDraft: null });
  const prior = refineMod ? versionsOf(refineMod, state.userVersions) : [];
  const context = refineMod
    ? { gameId: refineMod.gameId, category: refineMod.category, modId: refineMod.id, modName: refineMod.name, version: prior.length + 1 }
    : { gameId: sel.gameId, category: sel.category };

  const ctx: Ctx = { createdModId: null, path: [], rgb: "167 139 250", finished: false, startedAt: performance.now() };
  useStore.setState({
    job: {
      id: "pending",
      status: "connecting",
      prompt: text,
      model: state.modelAuto && autoPick ? autoPick : model.id,
      images: images.map((i) => i.url),
      credits: 0,
      refining: !!refineMod,
      version: refineMod ? prior.length + 1 : 1,
      steps: [],
      files: [],
      startedAt: Date.now(),
    },
  });
  fx.setMode("thinking");
  fx.ripple(true);
  // A retarget (creator-warning deep link) applies to this one change only.
  const retarget = refineMod?.real ? state.retarget : null;
  if (state.retarget) useStore.setState({ retarget: null });

// The ONE door to Cyrus' own database. Cyrus code imports `cyrusDb` from here (never lib/db). It resolves through the host
// registry on every use, so setHost() (tests, a standalone deployment) takes effect immediately. Typed as CyrusDb: only
// Cyrus' own tables plus $transaction/raw SQL exist on it; platform tables must go through the host's methods.
import { getHost } from "./host";
import type { CyrusDb } from "./host";

export type { CyrusDb };
export const cyrusDb: CyrusDb = new Proxy({} as CyrusDb, {
  get(_t, prop) {
    const c = getHost().db as unknown as Record<PropertyKey, unknown>;
    const v = c[prop];
    return typeof v === "function" ? (v as (...a: unknown[]) => unknown).bind(c) : v;
  },
  set(_t, prop, value) { (getHost().db as unknown as Record<PropertyKey, unknown>)[prop] = value; return true; },
  has(_t, prop) { return prop in (getHost().db as object); },
});
