import { TRIGRAMS } from "./prompt-trigrams";

const KEYBOARD_RUNS = ["asdf", "sdfg", "dfgh", "fghj", "ghjk", "hjkl", "qwer", "wert", "erty", "rtyu", "tyui", "yuio", "uiop", "zxcv", "xcvb", "cvbn", "vbnm"];

/** Share of a word's letter triples (with edge markers) that real English words use: ~0.5-1 for words, ~0.1-0.3 for key mashing. */
export function wordPlausibility(w: string): number {
  const p = `^${w}$`;
  let hit = 0, all = 0;
  for (let i = 0; i + 3 <= p.length; i++) { all++; if (TRIGRAMS.has(p.slice(i, i + 3))) hit++; }
  return all ? hit / all : 1;
}

/** A latin word that no human wrote: no vowel, a long consonant run, a repeated letter, keyboard mashing, a repeated chunk, or letter patterns no word uses. */
export function isJunkWord(w: string): boolean {
  if (w.length < 4) return false;
  if (!/^[a-z]+$/.test(w)) return false;
  if (w.length >= 6 && /(.{2,4})\1{1,}/.test(w) && new Set(w).size <= Math.ceil(w.length / 2)) return true; // "wasdwasd", "fsfsfsf"
  if (w.length >= 5 && wordPlausibility(w) < 0.42) return true; // "kajhdakj", "hdkjahdadaw"
  if (!/[aeiouy]/.test(w)) return true; // "hjkl", "xcvbn"
  if (/[^aeiouy]{6,}/.test(w)) return true; // "asdfghjkl"
  if (/(.)\1{3,}/.test(w)) return true; // "aaaaa"
  return KEYBOARD_RUNS.some((k) => w.includes(k));
}

/** Null when the prompt may build; otherwise the customer-safe reason (always PROMPT_UNCLEAR_MESSAGE). */
export function promptProblem(raw: string): string | null {
