  if (letters < compact.length * 0.6) return PROMPT_UNCLEAR_MESSAGE; // mostly digits and symbols
  const words = text.toLowerCase().match(/\p{L}[\p{L}']*/gu) ?? [];
  if (words.length < 2) return PROMPT_UNCLEAR_MESSAGE;
  const unique = new Set(words);
  if (unique.size < 2) return PROMPT_UNCLEAR_MESSAGE; // "yo yo yo", "gun gun gun"
  if (words.length >= 5 && unique.size / words.length < 0.3) return PROMPT_UNCLEAR_MESSAGE; // repetition spam
