// Cyrus PROMPT COACH: one coach template per archetype of the Minecraft coverage matrix
// (lib/cyrus/adapters/minecraft-coverage.json, 85 archetypes). A template says how to RECOGNISE the kind of mod a prompt
// asks for (`match`, plain word rules, no model) and which details that kind of mod needs to be built right the first
// time (`dims`, the gap ids of ./analyze.ts) plus the numbers to ask for with sensible defaults (`fields`).
// test/cyrus-coach.test.ts fails when an archetype in the coverage matrix has no template here (or the other way).
// Pure + client-safe (no JSON import here: the 136 KB matrix stays server side, see ./catalogue.ts).

export const GAP_IDS = [
  "what", "trigger", "numbers", "limits", "dimensions", "scope", "persistence", "config",
  "commands", "performance", "edgeCases", "antiAbuse", "modes", "feedback", "version",
] as const;
export type GapId = (typeof GAP_IDS)[number];

/** A number the coach asks for, prefilled with a sensible default the user can change. */
export type CoachField = { key: string; label: string; def: string; unit?: string };
export type CoachTemplate = {
  id: string;
  /** Word rules that recognise the archetype; more hits = better match. */
  match: RegExp[];
  /** The details this kind of mod needs (added to the base set of every request). */
  dims: GapId[];
  /** The numbers to ask for (the "numbers" / "limits" questions). */
  fields?: CoachField[];
  /** Trigger choices for the "when" question (first = default). */
  triggers?: string[];
};

const f = (key: string, label: string, def: string, unit?: string): CoachField => ({ key, label, def, ...(unit ? { unit } : {}) });
const T = (id: string, match: RegExp[], dims: GapId[], fields?: CoachField[], triggers?: string[]): CoachTemplate => ({ id, match, dims, ...(fields ? { fields } : {}), ...(triggers ? { triggers } : {}) });

const CMD = "commands" as const;
const CD = (d = "30") => f("cooldown", "Cooldown", d, "seconds");

export const COACH_TEMPLATES: CoachTemplate[] = [
  // commands, gui, hud
  T("custom_commands", [/\b(text commands?|custom commands?|command aliases?|aliases?|block(?:ed)? (?:the )?commands?|\/rules|\/discord|hide (?:\/pl|plugins))\b/i], [CMD, "config"]),
  T("utility_commands", [/\/(?:heal|feed|fly\w*|gamemode|gm\b|god|repair|hat)\b/i, /\b(heal|feed|fly ?toggle|god mode)\b/i], [CMD, "limits"], [CD("60")]),
  T("dialog_forms", [/\b(dialog(?:ue)? screens?|dialogs?|forms?|text input|accept\s*\/\s*decline|confirm(?:ation)? screens?)\b/i], ["trigger", CMD, "edgeCases"]),
  T("menus_gui", [/\b(gui|menus?|chest menu|server menu|selector)\b/i], [CMD, "feedback"], undefined, ["Opened with a command", "Opened by right-clicking an item", "Opened by clicking an NPC"]),
  T("bossbar_titles", [/\b(boss ?bars?|titles?|action ?bar|countdowns?)\b/i], ["trigger", "numbers", "feedback"], [f("duration", "How long it shows", "10", "seconds")]),
  T("hud_glyphs", [/\b(mana|stamina|energy|thirst) (?:bars?|meters?)|\bhud\b|\bicons? above the hotbar\b/i], ["numbers", "feedback", "persistence"], [f("max", "Bar maximum", "100"), f("regen", "Refills per second", "5")]),
  T("sidebar", [/\b(sidebar|scoreboard)\b/i], ["numbers", "feedback"], [f("refresh", "Updates every", "1", "seconds")]),
  T("tablist", [/\b(tab ?list|tab header|tab footer|player list header)\b/i], ["feedback"]),
  // utility
  T("afk", [/\bafk\b|\bidle\b|\bnot moving\b/i], ["numbers", "edgeCases", "feedback"], [f("after", "Marked AFK after", "5", "minutes"), f("kick", "Kick after", "30", "minutes")]),
  T("books_guides", [/\b(rule ?books?|written books?|guide ?books?|books?)\b/i], ["trigger", CMD]),
  T("graves", [/\b(graves?|death chests?|tombstones?)\b/i], ["persistence", "edgeCases", "antiAbuse", "numbers"], [f("expire", "Grave opens to everyone after", "15", "minutes")]),
  T("sign_tools", [/\bsigns?\b/i], ["edgeCases", CMD]),
  // mechanics, rewards, management
  T("fishing", [/\b(fishing|fish(?:es)? up|catch(?:es)? (?:a )?fish|fish catches)\b/i], ["numbers", "antiAbuse"], [f("chance", "Treasure chance", "10", "%")]),
  T("playtime_rewards", [/\b(daily (?:login )?rewards?|login streaks?|streaks?|playtime rewards?|daily reward)\b/i], ["persistence", "numbers", "antiAbuse"], [f("reset", "Streak resets after missing", "1", "day")]),
  T("voting", [/\b(vote|voting|votifier|server lists?)\b/i], ["edgeCases"]),
  T("login_gate", [/\b(maintenance(?: mode)?|whitelist|allow(?:ed)? list|join gate|kick(?:s|ed)? new joins?)\b/i], [CMD, "modes", "config"]),
  T("world_management", [/\b(multi ?world|create (?:a )?(?:new )?world|unload (?:a )?world|\/mw)\b/i], [CMD, "persistence"]),
  // moderation, permissions, protection
  T("anti_cheat", [/\b(anti[- ]?cheat|cheat(?:ers|ing)?|fly(?:ing)? hacks?|speed hacks?|reach hacks?)\b/i], ["numbers", "feedback", "edgeCases"], [f("speed", "Speed that counts as too fast", "12", "blocks per second")]),
  T("moderation", [/\b(mute|tempban|ban|freeze|warn(?:ings)?|moderation)\b/i], [CMD, "persistence", "feedback"]),
