  T("anti_grief_log", [/\b(block log(?:ging|s)?|rollback|\/inspect|grief log|who broke)\b/i], ["numbers", "persistence", CMD, "performance"], [f("keep", "History kept for", "3", "days")]),
  T("claims", [/\b(land claims?|claims?|\/claim|claim(?:ed)? chunks?|trust(?:ed)?)\b/i], ["numbers", "persistence", CMD, "edgeCases"], [f("max", "Claims per player", "4", "chunks")]),
  T("regions", [/\b(safe ?zones?|regions?|protected areas?|spawn protection|no pvp zone)\b/i], ["dimensions", "edgeCases", "config"], [f("size", "Area size", "64", "blocks square")]),
  // audio, progression
  T("custom_music", [/\b(music(?: discs?)?|songs?|soundtrack|background music|jukebox)\b/i], ["trigger", "dimensions", "numbers"], [f("volume", "Volume", "80", "%")]),
  T("advancements", [/\b(advancements?|achievements?)\b/i], ["numbers"]),
  T("jobs_skills", [/\b(jobs?|skills?|mcmmo|skill levels?)\b/i], ["numbers", "persistence", "feedback"], [f("xp", "XP per action", "5"), f("level", "Bonus every", "10", "levels")]),
  T("quests", [/\b(quests?|missions?|bount(?:y|ies)|objectives?)\b/i], ["numbers", "persistence", "feedback", CMD], [f("goal", "Goal count", "10"), f("reward", "Reward", "1 diamond")]),
  // chat
  T("announcer", [/\b(announcer|broadcasts?|tips?|motd|auto ?messages?)\b/i], ["numbers", "config"], [f("every", "Every", "5", "minutes")]),
  T("chat_channels", [/\b(chat channels?|staff chat|local chat|global chat|\/ch\b)\b/i], [CMD, "numbers"], [f("range", "Local chat range", "100", "blocks")]),
  T("chat_filter", [/\b(chat filter|swear(?:ing)?|bad words|anti[- ]?spam|caps|profanity)\b/i], ["numbers", "config", "edgeCases"], [CD("2")]),
