  T("private_messages", [/\b(private messages?|\/msg|\/pm|\/r\b|\/reply|whispers?|offline mail|\/mail)\b/i], [CMD, "persistence"]),
  // social
  T("clans_teams", [/\b(clans?|factions?|parties|party|teams?|guilds?)\b/i], [CMD, "persistence", "numbers", "edgeCases"], [f("size", "Max members", "10")]),
  T("leaderboards", [/\b(leaderboards?|top \d+|\/top|baltop|rankings?|stats?)\b/i], ["numbers", "persistence", "feedback"], [f("size", "Places shown", "10")]),
