  T("backpacks", [/\b(backpacks?|extra storage|\/bp\b|portable storage)\b/i], ["numbers", "persistence", "antiAbuse"], [f("rows", "Rows of storage", "3")]),
  T("custom_enchantments", [/\b(enchant(?:ment|ments|s)?)\b/i], ["numbers", "trigger"], [f("levels", "Levels", "I to III"), f("chance", "Effect chance per hit", "20", "%")]),
  T("custom_food", [/\b(food|foods|eat(?:en|s)?|drinks?|snacks?|rolls?)\b/i], ["numbers", "feedback"], [f("effect", "Effect and length", "Regeneration for 5", "seconds")]),
  T("custom_weapons", [/\b(swords?|blades?|weapons?|staffs?|wands?|scythes?|axes?|hammers?|maces?|spears?|guns?|pistols?|rifles?|daggers?|katanas?)\b/i], ["trigger", "numbers", "limits", "feedback", "antiAbuse"], [f("damage", "Ability damage", "6", "hearts"), CD("5"), f("range", "Range", "8", "blocks")], ["On right-click", "When it hits a mob or player", "While sneaking + right-click", "On the F key (swap hands)"]),
