  T("animated_creatures", [/\b(animated (?:creatures?|mobs?|models?)|own 3d model|custom (?:mob )?models?|creature with)\b/i], ["numbers", "trigger", "feedback", "version"], [f("health", "Health", "100"), f("size", "Size", "3", "blocks tall")]),
  T("bosses", [/\b(boss(?:es)?|mini-?boss|phases?|raid)\b/i], ["numbers", "trigger", "feedback", "antiAbuse", "edgeCases"], [f("health", "Boss health", "300"), f("phase", "Second phase at", "50", "% health"), f("minions", "Minions per summon", "4")], ["Summoned with a command", "Spawns at a set place every night", "Spawns from an item"]),
  T("custom_mobs", [/\b(custom mobs?|zombies?|skeletons?|creepers?|spiders?|mobs? (?:that|with)|brute|monsters?)\b/i], ["numbers", "trigger", "antiAbuse", "dimensions"], [f("health", "Health", "60"), f("damage", "Hit damage", "4", "hearts")]),
  T("mob_ai", [/\b(follows?|flee|guards?|attack(?:s)? mobs|mob (?:ai|behaviou?r)|golems? guard)\b/i], ["numbers", "edgeCases"], [f("range", "Range", "16", "blocks")]),
  T("mounts_vehicles", [/\b(mounts?|rideable|ride|steer|vehicles?|saddled?)\b/i], ["edgeCases", "version"]),
  T("pets", [/\b(pets?|companions?|tameable)\b/i], [CMD, "edgeCases", "persistence"]),
  T("spawners_mob_rules", [/\b(spawners?|spawn rates?|natural spawn(?:s|ing)?|mob spawning|spawn delay|phantoms? spawning)\b/i], ["numbers", "limits", "dimensions", "performance", "antiAbuse"], [f("delay", "Spawn delay", "20", "seconds"), f("max", "Max mobs nearby", "6")]),
  // world
  T("structure_placement", [/\b(structures?|schematics?|saved builds?|place a (?:house|hut|build))\b/i], [CMD, "edgeCases", "dimensions"]),
  T("world_events", [/\b(world events?|meteors?|weather|day ?night|storms?|eclipse|blood moon)\b/i], ["trigger", "numbers", "feedback", "dimensions"], [f("every", "Happens every", "2", "hours")]),
  T("worldgen", [/\b(biomes?|dimensions? (?:with|called|reachable)|custom dimension|world ?gen(?:eration)?|caverns?|ores? generat\w*)\b/i], ["dimensions", "edgeCases", "version"]),
];

export const TEMPLATE_BY_ID: Record<string, CoachTemplate> = Object.fromEntries(COACH_TEMPLATES.map((t) => [t.id, t]));

/** The best-matching archetype for a request (null = none clearly matches; the generic questions apply). */
export function matchArchetype(text: string): { id: string; hits: number } | null {
  const t = text ?? "";
  let best: { id: string; hits: number } | null = null;
  for (const tpl of COACH_TEMPLATES) {
    let hits = 0;
    for (const re of tpl.match) {
      const g = new RegExp(re.source, re.flags.includes("g") ? re.flags : `${re.flags}g`);
      hits += (t.match(g) ?? []).length;
    }
    if (hits > 0 && (!best || hits > best.hits)) best = { id: tpl.id, hits };
  }
  return best;
}

