// Cyrus PROMPT COACH: deterministic prompt-quality analysis (pure TypeScript, NO model call, zero cost, unit-tested in
// test/cyrus-coach.test.ts). Runs on the plan screen BEFORE anything is held. It answers: for THIS kind of request
// (archetype of the coverage matrix + what the words imply: heavy work, world changes, saved state, things it creates),
// on THIS game/version, which details are missing that a builder needs to get it right the first time:
//   trigger / when, exact numbers and limits, worlds/dimensions, scope (what must stay unchanged on a change request),
//   persistence and config wishes, commands and permissions, performance bounds, edge cases and what must NOT happen,
//   anti-abuse, modes, player feedback, version.
// It also flags phrasing the Haiku intake guard misreads (instructions to the AI, "keep everything exactly as is",
// unbounded or crash/lag wording, hidden privileges) and suggests describing the mod instead (2026-10-12 false refusal,
// fix/cyrus-guard-change-requests 4a2a5b3d2e), and collects the honest capability lines the user should see before spend.
// Output: { score 0-100, level great|good|vague, gaps [{id, question, why, example, input}], strengths, ... }.
import { ruleNeeds } from "../planner/rules";
import { LANE_META, type Lane } from "../planner/lanes";
import type { PlannedLane } from "../planner/decide";
import { GAP_IDS, TEMPLATE_BY_ID, matchArchetype, type CoachField, type CoachTemplate, type GapId } from "./archetypes";
import { archetypeFacts } from "./catalogue";

export const COACH_REPORT_VERSION = 1;
export type CoachLevel = "great" | "good" | "vague";

export type CoachInputSpec =
  | { kind: "chips"; options: string[]; multi: boolean; defaults: string[]; extra?: string }
  | { kind: "fields"; fields: CoachField[] }
  | { kind: "text"; placeholder: string; def: string };

export type CoachGap = { id: GapId; question: string; why: string; example: string; input: CoachInputSpec; weight: number; partial?: boolean };
export type GuardRisk = { id: string; phrase: string; why: string; suggestion: string; /** an instruction-like sentence the compiler leaves out */ drop: boolean };
export type ChangeContext = { name: string; version?: number; summary?: string | null; paths?: string[] };
export type CoachReport = {
  v: typeof COACH_REPORT_VERSION;
  score: number;
  level: CoachLevel;
  kind: "new" | "change";
  version: string;
  archetype: { id: string; label: string; status: string } | null;
  /** Every missing detail, most important first. */
  gaps: CoachGap[];
  /** The 3-6 questions the panel asks (a subset of gaps). */
  questions: CoachGap[];
  strengths: string[];
  guardRisks: GuardRisk[];
  /** Honest limits for this request on this game/version (archetype, version, platform, planned lanes). */
  capability: string[];
  /** Change requests only: what the change keeps, and planned lanes the text does not ask for. */
  change: { target: string; kept: string[]; unasked: { lane: Lane; label: string }[] } | null;
  /** A name for the mod when the text gives one ("called X", "a chunk mirror mod"). */
  name: string | null;
  words: number;
};

export type CoachInput = {
  text: string;
  version: string;
  game?: string;
  change?: ChangeContext | null;
  /** The plan screen's lanes (lib/cyrus/planner/decide.ts), for capability lines and the change-lane check. */
  lanes?: Pick<PlannedLane, "lane" | "state" | "label" | "warning" | "capability">[] | null;
};

// ---------- word rules (what a prompt already says) ----------
const VERSION_RE = /\b(1\.\d{1,2}(?:\.\d{1,2})?|26\.\d(?:\.\d{1,2})?)\b/g;
const NUM_WORDS = /\b(one|two|three|four|five|six|seven|eight|nine|ten|twelve|fifteen|twenty|thirty|fifty|hundred|double|twice|half|triple)\b/gi;
export const SAYS: Record<Exclude<GapId, "what" | "numbers" | "version">, RegExp> = {
  trigger: /\b(when(?:ever)?|on (?:join|death|kill|hit|right|left|break|place|spawn|login|respawn|first join|use)|right[- ]?clicks?|left[- ]?clicks?|sneak\w*|every \d+|every (?:few|second|minute|hour|day|night|morning)|each (?:time|day|hour|minute|night)|after (?:\d|a |the |every)|if (?:a|the|you|they|someone|anyone|it)|upon|while|once (?:a|the|you|they)|by (?:typing|running|using)|\/[a-z][\w-]*|commands?|triggers?|at (?:dawn|night|midnight|sunrise|sunset)|daily|hourly|press(?:es|ing)?|hold(?:s|ing)?|eats?|drinks?|dies|kills?|joins?|places?|breaks?|spawns? from|hits?)\b/i,
  limits: /\b(max(?:imum)?|min(?:imum)?|at most|at least|up to|no more than|limit(?:ed|s)?|caps?(?:ped)?|cooldowns?|only \d+|per (?:player|day|hour|minute|second|tick|chunk|spawn)|in total|clamp\w*)\b/i,
  dimensions: /\b(overworld|nether|the end|end dimension|all (?:worlds|dimensions)|every (?:world|dimension)|dimensions?|any world|each world|worlds? (?:named|called)|world names?|per world|only in (?:the )?\w+ world)\b/i,
  scope: /\b(keep(?:s|ing)?|kept|unchanged|stays?|same as (?:before|now)|don'?t change|do not change|leave|without changing|only change|existing|as it is now|current (?:behaviou?r|features?|commands?|config))\b/i,
  persistence: /\b(save[sd]?|saving|persist\w*|remember\w*|restarts?|reboots?|data file|stored?|storage|database|kept across|survives?|across sessions|yml|json file|to (?:a|the) file|reset(?:s)? (?:on|when|after)|forget\w*)\b/i,
  config: /\b(config(?:urable|\.yml|s)?|settings?|adjustable|customi[sz]able|tunable|editable|in the config|reload)\b/i,
  commands: /(?:^|\s)\/[a-z][\w-]*|\b(commands?|permissions?|perm(?:ission)? nodes?|ops?|operators?|admins?|staff)\b/i,
  performance: /\b(tps|lag\w*|per tick|ticks?|async\w*|queue\w*|throttl\w*|spread (?:over|across|out)|batch\w*|budget|performance|efficient\w*|bounded|lightweight|pause\w* (?:if|when)|unloaded chunks?|chunks? per)\b/i,
  edgeCases: /\b(never|must not|mustn'?t|should not|shouldn'?t|don'?t|do not|doesn'?t|cannot|can'?t|won'?t|without|except|unless|only if|only when|only (?:for|while|in|on)|skip\w*|ignore[sd]? (?:if|when)|instead|otherwise|prevent\w*|no (?:\w+ )?(?:drops?|damage|griefing|pvp)|not (?:in|on|for|when|while))\b/i,
  antiAbuse: /\b(dup(?:e|es|ing|lication|licate[sd]?)|anti[- ]?dup\w*|exploit\w*|abuse\w*|farm(?:ing|ed|able)?|no (?:item )?drops?|drops? nothing|drop no|no loot|no xp|anti[- ]?\w+|cheat\w*|spam\w*|cannot be (?:sold|dropped|traded|stolen|crafted)|soulbound|untradeable|once (?:per|a) (?:day|player)|only once)\b/i,
  modes: /\b(modes?|on\/off|turn(?:ed|s)? (?:it )?(?:on|off)|toggl\w*|enabl\w*|disabl\w*|switch(?:ed|es)? (?:it )?(?:on|off)|pause[sd]?|\/\w+ (?:on|off))\b/i,
  feedback: /\b(messages?|says?|tells?|shows?|displays?|broadcast\w*|titles?|action ?bar|sounds?|particles?|notif\w*|chat|announce\w*|boss ?bars?|scoreboard|warns?|warning|glow\w*|effects?|plays?)\b/i,
};

/** What the request implies (adds details it needs). */
const KIND = {
  heavy: /\b(chunks?|radius|every block|all blocks|whole (?:world|map|server)|entire (?:world|map|server)|every (?:mob|entity|player|chunk)|all (?:mobs|entities|chunks)|mirror\w*|cop(?:y|ies|ying)|duplicat\w*|clon\w*|spread\w*|areas?|explosions?|tnt|thousands?|hundreds?|lots of|mass\w*|waves?|hordes?|spawns? (?:more|extra|many)|replicat\w*|nearby chunks|surrounding)\b/i,
  world: /\b(blocks?|chunks?|worlds?|terrain|spawn(?:s|ing|ers?)?|mobs?|structures?|biomes?|places?|placed|placing|break(?:s|ing)?|broken|mine[sd]?|mining|teleport\w*|portals?|nether|overworld|the end)\b/i,
  stateful: /\b(homes?|warps?|balance|money|coins?|economy|claims?|stats?|levels?|xp|progress\w*|quests?|track\w*|count\w*|leaderboards?|kills?|streaks?|playtime|history|logs?|bank\w*|points|remember\w*|cooldowns?|owners?|trust\w*|backpacks?|mirrored)\b/i,
  creates: /\b(gives?|drops?|spawn\w*|creates?|generat\w*|rewards?|loot|duplicat\w*|cop(?:y|ies)|mirror\w*|clon\w*|places? (?:the same|a copy|copies)|summon\w*|sells?|buys?)\b/i,
  global: /\b(server[- ]wide|global\w*|every player|all players|everyone|world events?|whole server|everywhere)\b/i,
  item: /\b(swords?|wands?|staffs?|bows?|items?|weapons?|tools?|armou?r|potions?|food)\b/i,
  mob: /\b(mobs?|zombies?|skeletons?|creatures?|monsters?|boss(?:es)?|minions?|golems?|animals?|villagers?|spawners?)\b/i,
};

const WEIGHT: Record<GapId, number> = {
  what: 20, scope: 20, numbers: 15, performance: 12, trigger: 10, limits: 10, edgeCases: 10, antiAbuse: 10,
  dimensions: 8, persistence: 8, config: 6, commands: 6, modes: 5, feedback: 4, version: 3,
};
const STRENGTH: Record<GapId, string> = {
  what: "Describes what happens", trigger: "Says when it happens", numbers: "Gives exact numbers", limits: "Sets caps",
  dimensions: "Names the worlds", scope: "Says what stays the same", persistence: "Says what is saved", config: "Asks for settings",
  commands: "Names commands or permissions", performance: "Bounds the work", edgeCases: "Says what must not happen",
  antiAbuse: "Blocks duplication or farming", modes: "Can be switched on and off", feedback: "Says what players see", version: "Names the version",
};

// ---------- guard-trigger phrasing ----------
type RiskRule = { id: string; re: RegExp; why: string; suggestion: string; drop: boolean };
const RISKS: RiskRule[] = [
  { id: "ignore_instructions", drop: true, re: /\b(ignore|disregard|forget)\b[^.!?\n]{0,40}\b(instructions?|rules?|previous|above|safety|guidelines?|restrictions?|limits?)\b/i,
    why: "This reads like an instruction to the AI, so the safety check may refuse the whole request.", suggestion: "Leave it out and describe the mod: what happens, when, and the numbers." },
  { id: "keep_everything", drop: true, re: /\b(keep|leave)\s+(?:everything|it all|all of it|the (?:whole |entire )?(?:mod|plugin|code))\s+(?:else\s+)?(?:in (?:this|the) (?:mod|plugin)\s+)?(?:exactly\s+)?(?:as it is|as is|the same|unchanged|untouched|like it is)\b/i,
    why: "\"Keep everything exactly as it is\" can be read as an instruction to the AI rather than a description of the mod.", suggestion: "Name what must stay the same instead, for example \"The commands, permissions and config keys stay the same.\"" },
  { id: "dont_touch", drop: true, re: /\b(do not|don'?t|never)\s+(?:change|touch|modify|edit|rewrite)\s+(?:anything|any other|the rest|other (?:parts|code|files)|anything else)\b/i,
    why: "\"Don't change anything else\" reads like an instruction to the AI.", suggestion: "List the parts that stay the same (commands, settings, what each feature does now)." },
  { id: "ai_instruction", drop: true, re: /\b(you (?:must|have to|need to|are (?:an?|now))|as an ai|system prompt|pretend (?:to be|you)|act as (?:an?|if)|role ?play as|jailbreak|developer mode|do anything now|no matter what|don'?t refuse|do not refuse|without (?:any )?(?:restrictions?|filters?|rules))\b/i,
    why: "Talking to the AI (\"you must\", \"act as\", \"no matter what\") looks like an attempt to steer it, which the safety check refuses.", suggestion: "Describe the mod in the third person: \"The plugin does X when Y.\"" },
  { id: "bypass_checks", drop: true, re: /\b(bypass|disable|turn off|get around|skip)\b[^.!?\n]{0,30}\b(scan(?:ner|s)?|safety|security|checks?|filters?|guard|sandbox|anti[- ]?virus)\b/i,
    why: "Asking to get around the builder's checks is refused.", suggestion: "Leave it out; every Cyrus mod is compiled and safety-scanned." },
  { id: "crash_lag", drop: false, re: /\b(crash(?:es|ing)? (?:the )?(?:server|clients?|players?|game)|lag (?:the )?(?:server|players?|everyone)|lag machines?|crash exploits?|freeze the server)\b/i,
    why: "Code whose purpose is to crash or lag a server is refused.", suggestion: "If this is a stress or lag-protection feature, say what it is for and its limits (\"at most 200 mobs, pauses below 15 TPS\")." },
  { id: "unbounded", drop: false, re: /\b(infinite(?:ly)?|unlimited|endless(?:ly)?|limitless|every (?:single )?(?:chunk|block) in the (?:world|server|map)|(?:whole|entire) (?:world|map|server)|all (?:the )?(?:loaded )?chunks|as many as possible|no limits?|without (?:any )?limits?)\b/i,
    why: "Unbounded work is how a big feature turns into lag, and the safety check can read it as a lag exploit.", suggestion: "Give the bound: a radius, a maximum count, a cap per second." },
  { id: "hidden_privilege", drop: false, re: /\b(secret|hidden|invisible) (?:commands?|backdoors?|op|admin|permissions?|access)\b|\bbackdoors?\b|\b(?:give|gives|make)s? (?:me|myself|my account|the player \w+) (?:op|admin|operator)\b|\bonly (?:i|me) can\b|\bfor (?:my|player) (?:name|account|uuid)\b/i,
    why: "Hidden or player-specific privileges are refused.", suggestion: "Use a permission node the server owner hands out, for example \"mymod.admin (ops by default)\"." },
  { id: "dupe_glitch", drop: false, re: /\b(dup(?:e|ing)|duplicat\w+)\b[^.!?\n]{0,30}\b(items?|diamonds?|inventor(?:y|ies)|glitch(?:es)?|exploits?)\b/i,
    why: "Item duplication reads like an exploit unless it is clearly a game feature.", suggestion: "Say it is a deliberate feature and its limits, or that it PREVENTS duplication (\"mirrored blocks drop nothing\")." },
  { id: "personal_data", drop: false, re: /\b(grab|log|collect|steal|record|send)\w*\b[^.!?\n]{0,20}\b(ip(?: address)?e?s?|passwords?|tokens?|emails?)\b/i,
    why: "Collecting players' IPs, passwords or tokens is refused.", suggestion: "Leave it out; use permissions or bans by name instead." },
];

// ---------- helpers ----------
const words = (t: string) => (t.match(/\p{L}[\p{L}'-]*/gu) ?? []).length;
const stripVersions = (t: string) => t.replace(VERSION_RE, " ");
function countNumbers(t: string): number {
  const s = stripVersions(t);
  return (s.match(/\b\d+(?:[.,]\d+)?\b/g) ?? []).length + (s.match(NUM_WORDS) ?? []).length;
}
const sentenceOf = (text: string, index: number) => {
  const a = Math.max(text.lastIndexOf(".", index - 1), text.lastIndexOf("!", index - 1), text.lastIndexOf("?", index - 1), text.lastIndexOf("\n", index - 1)) + 1;
  const ends = [".", "!", "?", "\n"].map((c) => text.indexOf(c, index)).filter((i) => i >= 0);
  const b = ends.length ? Math.min(...ends) + 1 : text.length;
  return text.slice(a, b).trim();
};

export function guardRisks(text: string): GuardRisk[] {
  const out: GuardRisk[] = [];
  for (const r of RISKS) {
    const m = r.re.exec(text);
    if (m) out.push({ id: r.id, phrase: r.drop ? sentenceOf(text, m.index) : m[0], why: r.why, suggestion: r.suggestion, drop: r.drop });
  }
  return out;
}

const PLATFORM = /\b(forge|fabric|neoforge|quilt|client[- ]side mods?|client mods?|optifine|iris|shaders?|bedrock add-?ons?|behaviou?r packs?)\b/i;
const NETWORK = /\b(discord|web ?hooks?|https?:\/\/|api keys?|mysql|mongodb|redis|connect to (?:a|my|the|our) (?:website|web ?site|server|database|api)|download(?:s|ing)? (?:from|files?))\b/i;

/** A name from the text: "called X" / "named X", or "a chunk mirror mod" -> ChunkMirror. */
export function guessName(text: string): string | null {
  const called = /\b(?:called|named)\s+["“'`]?([A-Za-z][\w'-]*(?:\s+[A-Z][\w'-]*){0,2})/.exec(text);
  if (called) return called[1].replace(/["”'`]+$/, "").trim().slice(0, 40);
  const mod = /\b(?:a|an|the|my)\s+([a-z][a-z-]+(?:\s+[a-z][a-z-]+){0,2})\s+(?:mod|plugin)\b/i.exec(text);
  if (!mod) return null;
  const parts = mod[1].split(/\s+/).filter((w) => !/^(simple|cool|new|minecraft|custom|paper|small|basic|good|nice|great|fun|little|big|spigot|server)$/i.test(w));
  if (!parts.length) return null;
  return parts.map((w) => w[0].toUpperCase() + w.slice(1).toLowerCase()).join("").replace(/-/g, "").slice(0, 40);
}

/** Generative lanes a change build should not add unless the change text asks for them. */
export const GENERATIVE_LANES: readonly Lane[] = ["texture", "itemStates", "sound", "model3d", "creature", "designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion", "datapack", "worldgen", "library"];

/** Lanes planned for a CHANGE that its text does not ask for (the word rules say no). */
export function unaskedChangeLanes(text: string, lanes: Pick<PlannedLane, "lane" | "state">[], game = "minecraft"): Lane[] {
  const asked = new Set(ruleNeeds(text, game).filter((n) => n.need).map((n) => n.lane));
  return lanes.filter((l) => l.state === "build" && GENERATIVE_LANES.includes(l.lane) && !asked.has(l.lane)).map((l) => l.lane);
}

/** What a change keeps, in customer words, from what the client knows about the mod. */
export function keptFromBase(c: ChangeContext): string[] {
  const out: string[] = [];
  const summary = (c.summary ?? "").replace(/\s+/g, " ").trim();
  if (summary) out.push(`What ${c.name} does now: ${summary.slice(0, 160).replace(/\.?$/, ".")}`);
  else out.push(`What ${c.name} does now`);
  const p = c.paths ?? [];
  const has = (re: RegExp) => p.some((x) => re.test(x));
  if (!p.length || has(/plugin\.yml$/)) out.push("Its commands and permissions");
  if (!p.length || has(/config\.yml$/)) out.push("Its config.yml keys and their current defaults");
  if (has(/(^|\/)designs?\//)) out.push("Its item, menu and boss designs");
  if (has(/\.(png|ogg)$/) || has(/assets\//)) out.push("Its textures and sounds");
  return out;
}

// ---------- questions ----------
type Ctx = { tpl: CoachTemplate | null; text: string; kinds: Record<keyof typeof KIND, boolean>; version: string; name: string | null; change: ChangeContext | null };

const slug = (n: string | null) => (n ?? "mymod").replace(/[^A-Za-z0-9]/g, "").toLowerCase() || "mymod";

function numberFields(c: Ctx): CoachField[] {
  if (c.tpl?.fields?.length) return c.tpl.fields;
  const out: CoachField[] = [];
  if (/\bchunks?\b/i.test(c.text) || /\b(radius|nearby|surrounding|around)\b/i.test(c.text)) out.push({ key: "radius", label: "Radius", def: "4 (max 8)", unit: "chunks" });
  if (c.kinds.mob) out.push({ key: "mobs", label: "Max mobs per event", def: "20" });
  if (c.kinds.item) out.push({ key: "cooldown", label: "Cooldown", def: "10", unit: "seconds" }, { key: "damage", label: "Damage", def: "4", unit: "hearts" });
  if (!out.length) out.push({ key: "main", label: "The main number (how much, how often, how far)", def: "" });
  return out.slice(0, 4);
}
function limitFields(c: Ctx): CoachField[] {
  const out: CoachField[] = [];
  if (c.kinds.mob) out.push({ key: "mobsTotal", label: "Max alive at once", def: "200" });
  if (c.kinds.heavy) out.push({ key: "perAction", label: "Max changes per action", def: "100" });
  if (c.kinds.stateful || c.kinds.creates) out.push({ key: "perPlayer", label: "Max per player", def: "5" });
  if (!out.length) out.push({ key: "cap", label: "Upper limit", def: "" });
  return out.slice(0, 3);
}

function question(id: GapId, c: Ctx): Omit<CoachGap, "weight"> {
  const name = c.name ?? (c.change?.name ?? null);
  const cmd = slug(name);
  switch (id) {
    case "what": return { id, question: "What should happen in the game, step by step?", why: "A short idea leaves every detail to guesswork, and fixing guesses later costs more than writing them down now.",
      example: "When a player places a block, the same block also appears at the same spot in the chunks around it.", input: { kind: "text", placeholder: "Describe what players see happen", def: c.text } };
    case "trigger": return { id, question: "When does it happen?", why: "Without a trigger Cyrus has to pick one, and it may not be the one you meant.", example: c.tpl?.triggers?.[0] ?? "When a player places or breaks a block",
      input: { kind: "chips", multi: true, options: c.tpl?.triggers ?? (c.kinds.world ? ["When a player places or breaks a block", "When a mob spawns", "Every few minutes", "Only by a command"] : c.kinds.item ? ["On right-click", "When it hits a mob or player", "While sneaking"] : ["When a player runs a command", "When a player joins", "Every few minutes", "When a player right-clicks an item"]), defaults: [(c.tpl?.triggers ?? [c.kinds.world ? "When a player places or breaks a block" : c.kinds.item ? "On right-click" : "When a player runs a command"])[0]], extra: "Or describe it" } };
    case "numbers": return { id, question: "What are the exact numbers?", why: "Numbers decide balance and server load. Without them Cyrus picks defaults you may not want.", example: "Radius 4 chunks by default, maximum 8.", input: { kind: "fields", fields: numberFields(c) } };
    case "limits": return { id, question: "What are the caps?", why: "Caps keep a big feature from lagging the server or being farmed.", example: "At most 20 mirrored mobs per spawn and 200 alive in total.", input: { kind: "fields", fields: limitFields(c) } };
    case "dimensions": return { id, question: "Which worlds or dimensions?", why: "Blocks, mobs and teleports behave differently in the Nether and the End; say where it should work.", example: "Overworld, Nether and End, each switchable in config.yml.",
      input: { kind: "chips", multi: true, options: ["The Overworld", "The Nether", "The End", "Each can be switched on or off in config.yml"], defaults: ["The Overworld", "The Nether", "The End", "Each can be switched on or off in config.yml"] } };
    case "scope": {
      const kept = c.change ? keptFromBase(c.change) : ["What the mod does now", "Its commands and permissions", "Its config.yml keys and their current defaults"];
      return { id, question: "What must stay the same?", why: "Naming what stays protects the parts that already work from being rebuilt.", example: "The commands, permissions and config keys stay the same.",
        input: { kind: "chips", multi: true, options: [...kept, "No new items, menus, textures or sounds"], defaults: [...kept, "No new items, menus, textures or sounds"], extra: "Anything else that must not change" } };
    }
    case "persistence": return { id, question: "Should it remember things across restarts?", why: "Saved data needs a file and a size limit; without it everything resets when the server restarts.", example: "Saved in the plugin's own data file, kept across restarts.",
      input: { kind: "chips", multi: false, options: ["Saved across restarts in the plugin's own data file, with a size limit", "Resets when the server restarts"], defaults: ["Saved across restarts in the plugin's own data file, with a size limit"] } };
    case "config": return { id, question: "What should the server owner be able to change?", why: "Settings let you tune it without another build.", example: "Every number above in config.yml with a comment, plus a reload command.",
      input: { kind: "chips", multi: true, options: ["Every number above lives in config.yml with a comment", "A reload command", "All messages in config.yml"], defaults: ["Every number above lives in config.yml with a comment", "A reload command"] } };
    case "commands": return { id, question: "Which commands, and who can use them?", why: "Commands and permissions are part of the spec; guessed ones are hard to change later.", example: `/${cmd} status, on, off and reload, permission ${cmd}.admin.`,
      input: { kind: "fields", fields: [{ key: "command", label: "Commands", def: `/${cmd} status, on, off, reload` }, { key: "permission", label: "Permission", def: `${cmd}.admin (ops by default)` }] } };
    case "performance": return { id, question: "How much work may it do at once?", why: "A feature that touches many blocks, chunks or mobs must spread its work, or players feel lag.", example: "Spread over several ticks, pause if TPS stays below 15.",
      input: { kind: "chips", multi: true, options: ["Spread the work over several ticks (a configurable amount per tick)", "Pause automatically if TPS stays below 15 for 10 seconds and tell online operators", "A queue limit on pending work", "Work aimed at unloaded chunks is remembered and applied when they load"], defaults: ["Spread the work over several ticks (a configurable amount per tick)", "Pause automatically if TPS stays below 15 for 10 seconds and tell online operators"] } };
    case "edgeCases": return { id, question: "What must never happen?", why: "Edge cases you name are handled on purpose instead of by accident.", example: "If the matching spot is inside solid terrain or the void, skip it quietly.",
      input: { kind: "chips", multi: true, options: c.kinds.heavy || c.kinds.world ? ["Spots inside solid terrain or the void are skipped quietly", "Its own changes never trigger more changes", "Protected areas (spawn protection) are left alone"] : c.kinds.item ? ["It does nothing while the player is in creative or spectator mode", "It never hurts the player using it", "It never breaks blocks"] : ["It never runs for players without the permission", "Nothing happens if the target player is offline"], defaults: [], extra: "Something else that must not happen" } };
    case "antiAbuse": return { id, question: "How is it kept from being farmed or duplicated?", why: "Anything that creates blocks, items, mobs or money gets farmed unless you say how it is stopped.", example: "Blocks it places are remembered and drop nothing when broken.",
      input: { kind: "chips", multi: true, options: [...(c.kinds.world && c.kinds.heavy ? ["Blocks it places are remembered (kept across restarts) and drop nothing when broken"] : []), ...(c.kinds.mob ? ["Mobs it spawns drop no loot or XP"] : []), ...(c.kinds.item ? ["Its items cannot be crafted or copied"] : []), "Rewards at most once per player per day"], defaults: [(c.kinds.world && c.kinds.heavy) ? "Blocks it places are remembered (kept across restarts) and drop nothing when broken" : c.kinds.mob ? "Mobs it spawns drop no loot or XP" : c.kinds.item ? "Its items cannot be crafted or copied" : "Rewards at most once per player per day"] } };
    case "modes": return { id, question: "Can it be switched on and off?", why: "A switch lets you stop it without removing the mod.", example: `/${cmd} on and /${cmd} off for admins.`,
      input: { kind: "chips", multi: false, options: [`/${cmd} on and /${cmd} off for admins, on by default`, "Always on", "Off until an admin turns it on"], defaults: [`/${cmd} on and /${cmd} off for admins, on by default`] } };
    case "feedback": return { id, question: "What does the player see or hear?", why: "Feedback tells players it worked; without it a feature can feel broken.", example: "A short action bar message and a sound.",
      input: { kind: "chips", multi: true, options: ["A short action bar message", "A sound", "Particles", "A chat message"], defaults: ["A short action bar message"] } };
    case "version": return { id, question: `Is Minecraft ${c.version} your server's version?`, why: "What is possible depends on the version (the panel lists what is limited on this one).", example: `Built for Minecraft ${c.version}.`,
      input: { kind: "chips", multi: false, options: [`Yes, build it for ${c.version}`, "No, I will pick another version in the version picker first"], defaults: [`Yes, build it for ${c.version}`] } };
  }
}

// ---------- the analysis ----------
export function analyzePrompt(input: CoachInput): CoachReport {
  const text = String(input.text ?? "").replace(/\r/g, "").trim().slice(0, 4000);
  const game = input.game ?? "minecraft";
  const change = input.change ?? null;
  const w = words(text);
  const kinds = Object.fromEntries(Object.entries(KIND).map(([k, re]) => [k, re.test(text)])) as Ctx["kinds"];
  const match = matchArchetype(change ? `${change.name} ${change.summary ?? ""} ${text}` : text);
  const tpl = match ? TEMPLATE_BY_ID[match.id] ?? null : null;
  const facts = archetypeFacts(tpl?.id, input.version);
  const name = guessName(text) ?? change?.name ?? null;
  const ctx: Ctx = { tpl, text, kinds, version: input.version, name, change };

  // Which details matter for THIS request.
  const rel = new Set<GapId>(change ? ["what", "scope", "edgeCases"] : ["what", "trigger", "numbers", "edgeCases", "config"]);
  if (!change) for (const d of tpl?.dims ?? []) rel.add(d);
  if (change && /\b(radius|range|more|less|fewer|bigger|smaller|faster|slower|increase|decrease|raise|lower|double|half|longer|shorter|max(?:imum)?|limit)\b/i.test(text)) { rel.add("numbers"); rel.add("limits"); }
  if (kinds.heavy) { rel.add("performance"); rel.add("limits"); rel.add("numbers"); }
  if (kinds.heavy && kinds.world) rel.add("dimensions");
  if (kinds.stateful && !change) rel.add("persistence");
  if (kinds.creates && (kinds.heavy || kinds.mob || /\b(rewards?|loot|gives?|sells?)\b/i.test(text))) rel.add("antiAbuse");
  if (kinds.heavy || kinds.global) rel.add("modes");
  if (kinds.heavy && !change) rel.add("commands");

  // How well the text already covers each one.
  const nums = countNumbers(text);
  const mentioned = [...stripVersions("").matchAll(/x/g)].length; // placeholder for clarity: no-op
  void mentioned;
  const versions = [...text.matchAll(VERSION_RE)].map((m) => m[1]);
  const otherVersion = versions.find((v) => v !== input.version && !input.version.startsWith(`${v}.`)) ?? null;
  const covered = (id: GapId): number => {
    if (id === "what") return w >= 12 ? 1 : w >= 6 ? 0.5 : 0;
    if (id === "numbers") return nums >= 2 ? 1 : nums === 1 ? 0.5 : 0;
    if (id === "version") return otherVersion ? 0 : versions.includes(input.version) ? 1 : 0.5;
    return SAYS[id].test(text) ? 1 : 0;
  };
  let total = 0, got = 0;
  const gaps: CoachGap[] = [];
  const strengths: string[] = [];
  for (const id of GAP_IDS) {
    if (!rel.has(id)) continue;
    const c = covered(id);
    total += WEIGHT[id];
    got += WEIGHT[id] * c;
    if (c >= 1) strengths.push(id === "numbers" ? `${STRENGTH.numbers} (${nums})` : STRENGTH[id]);
    else gaps.push({ ...question(id, ctx), weight: WEIGHT[id], ...(c > 0 ? { partial: true } : {}) });
  }
  gaps.sort((a, b) => b.weight - a.weight || GAP_IDS.indexOf(a.id) - GAP_IDS.indexOf(b.id));

  const risks = guardRisks(text);
  let score = total ? Math.round((100 * got) / total) : 0;
  if (w < 6) score = Math.min(score, 25);
  else if (w < 12) score = Math.min(score, 45);
  else if (w < 25) score = Math.min(score, 70);
  if (w >= 60 && gaps.length <= 2) score += 5;
  score -= Math.min(30, risks.length * 12);
  if (otherVersion) score -= 5;
  score = Math.max(0, Math.min(100, score));
  const level: CoachLevel = score >= 75 ? "great" : score >= 50 ? "good" : "vague";

  // Honest capability lines (deduplicated, shown before spend).
  const capability: string[] = [];
  const push = (s: string | null | undefined) => { if (s && !capability.includes(s)) capability.push(s); };
  if (otherVersion) push(`Your text mentions Minecraft ${otherVersion}, but this mod is built for ${input.version}. Change the version in the version picker; the text does not change it.`);
  if (PLATFORM.test(text)) push("Cyrus builds Paper server plugins (with a resource pack the server sends to players). Forge, Fabric and other client mods, shaders and client-side features are not built; players join with a normal client.");
  if (NETWORK.test(text)) push("Cyrus mods cannot use networking (Discord, websites, databases, downloads): that capability is not switched on yet. Cyrus can build the in-game part.");
  if (facts && facts.status !== "covered") for (const l of facts.limits) push(l);
  if (facts) for (const l of facts.versionLines) push(l);
  for (const l of input.lanes ?? []) if ((l.state === "blocked" || (l.state === "build" && l.capability?.availability === "limited")) && l.warning) push(l.warning);

  // Change requests: what is kept, and planned lanes the change text does not ask for.
  const unasked = change && input.lanes ? unaskedChangeLanes(text, input.lanes, game) : [];
  const changeOut = change ? { target: change.version ? `${change.name} (v${change.version - 1} -> v${change.version})` : change.name, kept: keptFromBase(change), unasked: unasked.map((lane) => ({ lane, label: LANE_META[lane].label })) } : null;

  const n = level === "great" ? Math.min(3, gaps.length) : Math.min(6, Math.max(3, gaps.length));
  return {
