// Cyrus PROMPT COACH: the deterministic COMPILER. Turns the user's text plus the answers from the coach panel into a
// complete, well-structured prompt in the style of /root/agent-notes/cyrus-research/BI-chunkmirror-fresh-prompt.md:
//   header (plugin, name, version) / What it does / Numbers / Limits / Modes / No duplication / Dimensions /
//   Saved data / Performance / Must not happen / Player feedback / Commands / Config
// A change request compiles to "Change to <mod>: <change>" + "Unchanged: ..." (describing what stays, never an
// instruction to the AI: "keep everything exactly as it is" is what the intake guard refused on 2026-10-12).
// Pure + client-safe (no catalogue import): it only needs the report the plan route sent. It is also the fallback when
// the optional one-call "Rewrite for me" fails.
import type { CoachGap, CoachReport } from "./analyze";
import type { GapId } from "./archetypes";

export type CoachAnswer = { chips?: string[]; fields?: Record<string, string>; text?: string };
export type CoachAnswers = Partial<Record<GapId, CoachAnswer>>;

export const MAX_PROMPT = 4000;

/** The prefilled answers of every question (what the panel shows before the user touches anything). */
export function defaultAnswers(questions: readonly CoachGap[]): CoachAnswers {
  const out: CoachAnswers = {};
  for (const q of questions) {
    const i = q.input;
    if (i.kind === "chips") out[q.id] = { chips: [...i.defaults], text: "" };
    else if (i.kind === "fields") out[q.id] = { fields: Object.fromEntries(i.fields.map((f) => [f.key, f.def])) };
    else out[q.id] = { text: i.def };
  }
  return out;
}

const clean = (s: string) => s.replace(/\s+/g, " ").trim();
const sentence = (s: string) => { const t = clean(s); if (!t) return ""; const u = t[0].toUpperCase() + t.slice(1); return /[.!?]$/.test(u) ? u : `${u}.`; };
const lowerFirst = (s: string) => (s && !/^[A-Z]{2}|^\/|^[A-Z][a-z]+[A-Z]/.test(s) ? s[0].toLowerCase() + s.slice(1) : s);
export function joinList(items: string[]): string {
  const xs = items.map(clean).filter(Boolean);
  if (xs.length <= 1) return xs[0] ?? "";
  return `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`;
}

/** The user's text without the instruction-like sentences the coach flagged (they would only confuse the guard). */
export function withoutRiskySentences(text: string, report: Pick<CoachReport, "guardRisks">): string {
  let t = text;
  for (const r of report.guardRisks) if (r.drop && r.phrase) t = t.split(r.phrase).join(" ");
  return clean(t);
}

function chipsOf(a: CoachAnswer | undefined): string[] {
  return [...(a?.chips ?? []), ...(a?.text && clean(a.text) ? [clean(a.text)] : [])];
}
function fieldsLine(q: CoachGap | undefined, a: CoachAnswer | undefined): string {
  if (!q || q.input.kind !== "fields") return "";
  const parts: string[] = [];
  for (const f of q.input.fields) {
    const v = clean(a?.fields?.[f.key] ?? "");
    if (!v) continue;
    parts.push(`${f.label}: ${v}${f.unit && !v.toLowerCase().includes(f.unit.toLowerCase()) ? ` ${f.unit}` : ""}`);
  }
  return parts.join("; ");
}

const DIMS = ["The Overworld", "The Nether", "The End"];

export type CompileInput = { text: string; report: Pick<CoachReport, "kind" | "version" | "name" | "questions" | "guardRisks" | "change">; answers: CoachAnswers };

export function compilePrompt(i: CompileInput): string {
  const { report, answers } = i;
  const q = (id: GapId) => report.questions.find((x) => x.id === id);
  const asked = (id: GapId) => !!q(id);
  const base = withoutRiskySentences(i.text, report);
  const whatText = asked("what") && clean(answers.what?.text ?? "") ? clean(answers.what!.text!) : base;
  const lines: string[] = [];

  if (report.kind === "change" && report.change) {
    lines.push(`Change to ${report.change.target}: ${sentence(whatText)}`);
  } else {
    lines.push(`Build a Paper plugin${report.name ? ` called ${report.name}` : ""} for Minecraft ${report.version}.`);
    lines.push(`What it does: ${sentence(whatText)}`);
  }
  const trig = chipsOf(answers.trigger);
  if (asked("trigger") && trig.length) lines.push(`When: ${sentence(joinList(trig.map(lowerFirst)))}`);
  const nums = fieldsLine(q("numbers"), answers.numbers);
  if (nums) lines.push(`Numbers: ${sentence(nums)} All of them are configurable.`);
  const lim = fieldsLine(q("limits"), answers.limits);
  if (lim) lines.push(`Limits: ${sentence(lim)}`);
  const modes = chipsOf(answers.modes);
  if (asked("modes") && modes.length) lines.push(`Modes: ${sentence(joinList(modes))}`);
  const abuse = chipsOf(answers.antiAbuse);
  if (asked("antiAbuse") && abuse.length) lines.push(`No duplication: ${abuse.map(sentence).join(" ")}`);
  const dims = chipsOf(answers.dimensions);
  if (asked("dimensions") && dims.length) {
    const worlds = dims.filter((d) => DIMS.includes(d)).map((d) => d.replace(/^The /, "the "));
    const rest = dims.filter((d) => !DIMS.includes(d));
    lines.push(`Dimensions: ${worlds.length ? `It works in ${joinList(worlds)}${worlds.length < 3 ? " only" : ""}.` : ""}${rest.length ? ` ${rest.map(sentence).join(" ")}` : ""} If the matching position is not valid there, it is skipped quietly.`.replace(/\s+/g, " ").trim());
  }
  const saved = chipsOf(answers.persistence);
  if (asked("persistence") && saved.length) lines.push(`Saved data: ${saved.map(sentence).join(" ")}`);
  const perf = chipsOf(answers.performance);
  if (asked("performance") && perf.length) lines.push(`Performance: ${perf.map(sentence).join(" ")}`);
  const never = chipsOf(answers.edgeCases);
  if (asked("edgeCases") && never.length) lines.push(`Must not happen: ${never.map(sentence).join(" ")}`);
  const fb = chipsOf(answers.feedback);
  if (asked("feedback") && fb.length) lines.push(`Player feedback: ${sentence(joinList(fb.map(lowerFirst)))}`);
  const cmd = fieldsLine(q("commands"), answers.commands);
  if (cmd) lines.push(`Commands: ${sentence(cmd)}`);
  const cfg = chipsOf(answers.config);
  if (asked("config") && cfg.length) lines.push(`Config: ${cfg.map(sentence).join(" ")}`);
  if (report.kind === "change") {
    const kept = chipsOf(answers.scope);
    if (kept.length) lines.push(`Unchanged: ${sentence(joinList(kept.map(lowerFirst)))} Only the parts described above change.`);
    else lines.push("Unchanged: everything not described above works as it does now.");
  }
  let out = lines.filter(Boolean).join("\n\n");
  if (out.length > MAX_PROMPT) out = out.slice(0, MAX_PROMPT - 1).replace(/\s+\S*$/, "") + "…";
  return out;
}

