// Cyrus PROMPT COACH: the optional one-click "Rewrite for me" (server flow; dependencies injectable so the path is tested
// with fakes and NO model call). ONE Haiku call on the build service (POST /coach, features.coach, $0.05 hard cap per
// call, shown to the customer before they press it as COACH_REWRITE_USD). Any failure, timeout or suspicious answer
// falls back to the deterministic compiler's draft (lib/cyrus/coach/compile.ts), so the customer always gets a prompt.
import { guardRisks } from "./analyze";
import { MAX_PROMPT } from "./compile";

/** What the panel shows before the click (measured on a one-turn Haiku call: a fraction of a cent to about one cent). */
export const COACH_REWRITE_USD: readonly [number, number] = [0.002, 0.01];

export type CoachAsk = (body: { text: string; draft: string; mcVersion: string; change?: { name: string } | null }) => Promise<{ text: string | null; costUsd: number; ms: number }>;
export type RewriteDeps = { ask?: CoachAsk; supports?: () => Promise<boolean>; timeoutMs?: number };
export type RewriteResult = { text: string; source: "model" | "compiler"; costUsd: number; ms: number | null; error: string | null };

const NUM = /\b\d+(?:[.,]\d+)?\b/g;

/** Validate the model's rewrite: plain text, sane length, no instruction-like phrasing, every number the customer typed kept. */
export function checkRewrite(raw: unknown, original: string): { ok: true; text: string } | { ok: false; why: string } {
  if (typeof raw !== "string") return { ok: false, why: "no text" };
  const text = raw.trim().replace(/^```\w*\s*/, "").replace(/\s*```$/, "").trim();
  if (text.length < 40) return { ok: false, why: "too short" };
  if (text.length > MAX_PROMPT) return { ok: false, why: "too long" };
  if (/<\/?(request|draft)>/i.test(text)) return { ok: false, why: "echoed the wrapper" };
  if (guardRisks(text).some((r) => r.drop)) return { ok: false, why: "instruction-like phrasing" };
  const nums = new Set(text.match(NUM) ?? []);
  const lost = (original.match(NUM) ?? []).filter((n) => !nums.has(n));
  if (lost.length) return { ok: false, why: `dropped the customer's numbers (${lost.slice(0, 3).join(", ")})` };
  return { ok: true, text };
}

export async function rewritePrompt(input: { text: string; draft: string; mcVersion: string; change?: { name: string } | null }, deps: RewriteDeps = {}): Promise<RewriteResult> {
  const fallback = (error: string, costUsd = 0, ms: number | null = null): RewriteResult => ({ text: input.draft, source: "compiler", costUsd, ms, error });
  if (!deps.ask) return fallback("rewrite not available");
  if (!(await (deps.supports ?? (async () => true))().catch(() => false))) return fallback("rewrite not available");
  const t0 = Date.now();
  try {
    const timeout = new Promise<null>((r) => setTimeout(() => r(null), deps.timeoutMs ?? 20000));
    const ans = await Promise.race([deps.ask(input), timeout]);
    if (!ans) return fallback("rewrite timed out");
    const c = checkRewrite(ans.text, input.text);
    if (!c.ok) return fallback(`rewrite rejected: ${c.why}`, ans.costUsd, ans.ms || Date.now() - t0);
    return { text: c.text, source: "model", costUsd: ans.costUsd, ms: ans.ms || Date.now() - t0, error: null };
  } catch (e) {
    return fallback(`rewrite failed: ${(e as Error).message.slice(0, 80)}`);
  }
}

