import { NextResponse } from "next/server";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { NOT_FOUND } from "@/app/api/mod-builder/_lib";
import { checkRateLimit } from "@/lib/rate-limit";
import { getVersion } from "@/lib/cyrus/versions/registry";
import { MB_VERSIONS } from "@/lib/modbuilder/types";
import { svcCoach, svcHealthCached } from "@/lib/cyrus/builder/client";
import { coachOn } from "@/lib/cyrus/coach/flags";
import { rewritePrompt } from "@/lib/cyrus/coach/rewrite";
import { isCoachEventKind, recordCoachEvent } from "@/lib/cyrus/coach/events";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Cyrus PROMPT COACH (CYRUS_PROMPT_COACH=1, else 404). Same private-preview gate as the plan route.
 *   POST { mode: "rewrite", prompt, draft, mcVersion, change?: { name } }
 *     -> { text, source: "model" | "compiler", costUsd, ms, error }   ONE Haiku call on the build service (features.coach),
 *        Nxeon's cost like the planner (a fraction of a cent to about one cent), rate-limited; any failure returns the
 *        deterministic draft (source "compiler"). Nothing is held or charged.
 *   POST { mode: "event", kind, prompt, mcVersion, requestKind, archetype?, scoreBefore?, scoreAfter?, level?, gaps? }
 *     -> { ok }   measurement row in CyrusCoachEvent through cyrusDb (fail soft; the prompt is stored as a hash only).
 */
export async function POST(req: Request) {
  if (!coachOn()) return NOT_FOUND();
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  let body: Record<string, unknown>;
  try { body = (await req.json()) as Record<string, unknown>; } catch { return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 }); }
  if (!body || typeof body !== "object" || Array.isArray(body)) return NextResponse.json({ error: "Invalid body" }, { status: 400 });
  const prompt = typeof body.prompt === "string" ? body.prompt.trim().slice(0, 4000) : "";
  const mcVersion = typeof body.mcVersion === "string" && getVersion(body.mcVersion) ? body.mcVersion : MB_VERSIONS[0];

  if (body.mode === "rewrite") {
    const draft = typeof body.draft === "string" ? body.draft.trim().slice(0, 4000) : "";
    if (prompt.length < 4 || draft.length < 4) return NextResponse.json({ error: "Describe the mod first." }, { status: 400 });
    const rl = checkRateLimit(`cy:coach-rw:${user.id}`, { max: 6, windowMs: 60_000 });
    if (!rl.ok) return NextResponse.json({ error: `Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
    const ch = body.change && typeof body.change === "object" && typeof (body.change as { name?: unknown }).name === "string" ? { name: String((body.change as { name: string }).name).slice(0, 60) } : null;
    const out = await rewritePrompt(
      { text: prompt, draft, mcVersion, change: ch },
      { ask: (b) => svcCoach(b), supports: async () => ((await svcHealthCached())?.features as { coach?: unknown } | undefined)?.coach === true },
    );
    void recordCoachEvent({ userId: user.id, kind: out.source === "model" ? "rewrite" : "rewrite_failed", requestKind: ch ? "change" : "new", game: "minecraft", mcVersion, prompt, rewriteUsd: out.costUsd });
    return NextResponse.json(out, { headers: { "Cache-Control": "no-store" } });
  }

  if (body.mode === "event") {
    if (!isCoachEventKind(body.kind) || body.kind === "rewrite" || body.kind === "rewrite_failed") return NextResponse.json({ error: "Unknown event" }, { status: 400 });
    if (!prompt) return NextResponse.json({ error: "Missing prompt" }, { status: 400 });
    const rl = checkRateLimit(`cy:coach-ev:${user.id}`, { max: 60, windowMs: 60_000 });
    if (!rl.ok) return NextResponse.json({ ok: false }, { status: 429 });
    const num = (v: unknown) => (typeof v === "number" ? v : null);
    const ok = await recordCoachEvent({
      userId: user.id, kind: body.kind, requestKind: body.requestKind === "change" ? "change" : "new", game: "minecraft", mcVersion, prompt,
      archetype: typeof body.archetype === "string" ? body.archetype : null, scoreBefore: num(body.scoreBefore), scoreAfter: num(body.scoreAfter),
      level: typeof body.level === "string" ? body.level : null, gaps: Array.isArray(body.gaps) ? (body.gaps as unknown[]).filter((g): g is string => typeof g === "string") : null,
    });
    return NextResponse.json({ ok }, { headers: { "Cache-Control": "no-store" } });
  }
  return NextResponse.json({ error: "Unknown mode" }, { status: 400 });
}

