// Before anything is spent: the prompt's score and level, honest capability lines, guard-trigger phrasing, and for a
// change request "This changes your existing mod" with what is kept. "Improve my prompt" opens a small panel: 3-6
// questions with prefilled defaults, compiled live into a structured prompt (lib/cyrus/coach/compile.ts) the user can
// edit, accept, or ignore ("Keep my text": never blocked). Optional "Rewrite for me" = ONE Haiku call (cost shown first;
// failure falls back to the compiled prompt). Styling copies PlanSheet (cy tokens, the one violet accent, amber notices).
import { useEffect, useMemo, useState } from "react";
import { compilePrompt, defaultAnswers, COACH_REWRITE_USD, type CoachAnswer, type CoachAnswers } from "@/lib/cyrus/coach/compile";
import type { CoachGap, CoachReport } from "@/lib/cyrus/coach/analyze";
import type { GapId } from "@/lib/cyrus/coach/archetypes";

type EventKind = "shown" | "opened" | "accepted" | "edited" | "skipped";
const LEVEL_LABEL: Record<CoachReport["level"], string> = { great: "Clear", good: "Good", vague: "Vague" };

const shownFor = new Set<string>();
let pendingAccept: { text: string; kind: "accepted" | "edited"; scoreBefore: number } | null = null;

/** Measurement (fire and forget; the server drops it while the coach or the table is off). */
export function coachEvent(kind: EventKind, text: string, version: string, report: CoachReport, extra: { scoreAfter?: number; scoreBefore?: number } = {}) {
  try {
    void fetch("/api/cyrus/coach", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ mode: "event", kind, prompt: text, mcVersion: version, requestKind: report.kind, archetype: report.archetype?.id ?? null, scoreBefore: extra.scoreBefore ?? report.score, scoreAfter: extra.scoreAfter ?? null, level: report.level, gaps: report.questions.map((q) => q.id) }),
    }).catch(() => undefined);
  } catch { /* measurement never breaks the plan screen */ }
}

function Chips({ q, a, onChange }: { q: CoachGap; a: CoachAnswer; onChange: (a: CoachAnswer) => void }) {
  if (q.input.kind !== "chips") return null;
  const { options, multi, extra } = q.input;
  const on = new Set(a.chips ?? []);
  const flip = (o: string) => {
    const next = multi ? (on.has(o) ? [...on].filter((x) => x !== o) : [...on, o]) : on.has(o) ? [] : [o];
    onChange({ ...a, chips: options.filter((x) => next.includes(x)) });
  };
  return (
    <div className="flex flex-wrap gap-1.5 pt-1">
      {options.map((o) => (
        <button key={o} type="button" aria-pressed={on.has(o)} onClick={() => flip(o)}
          className={`rounded-full px-2.5 py-1 text-left text-[11.5px] leading-snug ${on.has(o) ? "bg-[rgb(var(--glow)/0.18)] text-cy-ink" : "bg-[rgb(var(--glow)/0.06)] text-cy-muted hover:text-cy-ink"}`}>
          {on.has(o) ? "✓ " : ""}{o}
        </button>
      ))}
      {extra && <input value={a.text ?? ""} onChange={(e) => onChange({ ...a, text: e.target.value })} placeholder={extra} aria-label={`${q.question} ${extra}`}
        className="min-w-[180px] flex-1 rounded-lg bg-[rgb(var(--glow)/0.06)] px-2 py-1 text-[12px] text-cy-ink outline-none placeholder:text-cy-faint" />}
    </div>
  );
}

function Fields({ q, a, onChange }: { q: CoachGap; a: CoachAnswer; onChange: (a: CoachAnswer) => void }) {
  if (q.input.kind !== "fields") return null;
  return (
    <div className="grid gap-1.5 pt-1 sm:grid-cols-2">
      {q.input.fields.map((f) => (
        <label key={f.key} className="flex items-center gap-2 text-[11.5px] text-cy-muted">
          <span className="min-w-[96px]">{f.label}</span>
          <input value={a.fields?.[f.key] ?? ""} onChange={(e) => onChange({ ...a, fields: { ...(a.fields ?? {}), [f.key]: e.target.value } })} placeholder={f.def || "type a number"}
            className="w-full min-w-0 rounded-lg bg-[rgb(var(--glow)/0.06)] px-2 py-1 text-[12px] tabular-nums text-cy-ink outline-none placeholder:text-cy-faint" />
          {f.unit && <span className="text-cy-faint">{f.unit}</span>}
        </label>
      ))}
    </div>
  );
}

